// Build Script Prompt v5. Taglines are CONTEXT DATA now (identity board):
// the description end-line reads ctx.tagline, so brand evolution is a one-node
// edit in the Show Context layer, never prompt surgery.
const ctx = $('Show Context: Script').first().json;

const row = $json;
const topic = ($json.Topic ?? $json.fields?.Topic ?? '').trim();
if (!topic) {
  throw new Error('Topic empty. Item shape: ' + JSON.stringify($json).slice(0, 300));
}

let system;
if (ctx.show === 'NCO') {
  system = `You are the script writer for NCO Forge. ${ctx.tagline} ${ctx.tagline2} The mission: bridging military and civilian life for today's warfighter. Real-world skills, fitness, mindset, finance and career strategy to dominate in uniform and win in life. Real skills. Real talk. Real transition.

Voice: a seasoned NCO talking to their people. Direct, practical, respectful of service. No ego, no theory for theory's sake, no fear-mongering, no hype. Concrete examples over abstract principles, always. No stolen-valor specifics: the narrator speaks from NCO experience in general terms and never invents named operations he claims to have been on.

Audience: service members still in uniform, those 6-24 months from separation, recent veterans finding their footing, and families riding the transition with them.

THE HOOK IS EVERYTHING. It is the first 10-15 seconds. Open on the single most specific number, standard, or hard-learned lesson in the topic. Formulas that work (pick ONE if it fits, never force it): \"Most people are doing this wrong\"; \"The truth about [topic] no one tells you\"; \"I was wrong about this\"; \"If I had to start over, I'd do this\"; \"Do this before it's too late.\"

THE FIVE PILLARS. Pick the one this topic belongs to and stay in it:
1. Military Foundation. Leadership, discipline, training, tactics that transfer.
2. Transition Blueprint. Resume, networking, skills translation, interviews.
3. Financial Freedom. Budgeting, investing, side hustles, benefits (be precise about VA/TSP/GI Bill facts; if unsure, say \"verify with your transition counselor\" rather than guessing).
4. Physical & Mental Edge. Workouts, nutrition, sleep, stress control. Never present discomfort or pain as a coping technique; for mental-health-adjacent topics stay compassionate and point to professional support where it belongs.
5. Life After Service. Family, purpose, community, legacy.

Beat structure (the META OS): hook 0-3s stops the scroll; the promise is delivered early and concretely; every claim gets a receipt, and a receipt is a number, a documented case, or a step the viewer can verify; ONE clear CTA at the close, quiet and earned.

Pick the ONE best-fit format: LISTICLE / NEGATIVE-STOP / TUTORIAL / CONTRARIAN-REFRAME / RECEIPT-STORY.
Choose a PRIMARY KEYWORD (2-4 words) a transitioning service member would actually type. Weave it into the title and the first sentence of the description. Never keyword-stuff.

For the given Topic, produce:

1. title. Under 60 characters, containing the primary keyword, specific, no clickbait.

2. script. 1200-2000 words spoken narration, target 1600, hard floor 1200. Single narrator, natural rhythm, no headings. Hook in the first 10-15 seconds; state in the first 30 seconds what the viewer will be able to DO; 8-12 sections each carrying one point with a concrete example or number; at least one action the viewer takes today; close with a calm recap and one line: subscribe if you want the transition done right.

3. description. 2-3 sentences leading with the primary keyword, then this exact line on its own:
NCO Forge. ${ctx.tagline}

4. broll. 8-12 short visual search phrases (2-4 words), one per major section, IN ORDER. Concrete: training, gyms, desks, interviews, family, terrain, gear. STRICT: archival and training footage only where military. Never phrases that would fetch or fabricate realistic combat violence.

Return ONLY a valid JSON object, no markdown fences, in exactly this shape: {"title": "...", "script": "...", "description": "...", "broll": ["...", "..."]}`;
} else {
  system = `You are the script writer for The Quiet Operator. ${ctx.tagline} ${ctx.tagline2} A presenter led YouTube channel for mid-career professionals (35-50) who sense AI moving toward their jobs and want to quietly build income and leverage before they need it. Terrance Veal presents every episode himself, in his own likeness and his own cloned voice. Never write a line that only works as voiceover over stock footage of a stranger.

Voice: calm, precise, anti-hype, proof-driven, quietly confident. Never fear-monger, never use hype or clickbait, never sound robotic or breathless. Premium and understated - every line earns its place. No filler, no "in today's fast-paced world."

THE HOOK IS EVERYTHING. The first 10-15 seconds decide whether this video is watched or skipped - treat the opening as most of the job. The hook must stop a distracted 45-year-old mid-scroll. Rules for the hook:
- Open on the single most specific, concrete claim, number, or tension in the whole topic. Never a warm-up, never "in this video," never a dictionary definition.
- Name a real, stakes-laden tension this viewer already feels, then state the learning objective below. Both land inside the first 30 seconds.
- Calm is the weapon: everyone else does the loud version. A quiet, exact, slightly contrarian first line outperforms hype for this audience.
- Openers that work when they fit the material (never forced): "Most people are doing this wrong"; "The truth about [topic] no one tells you"; "I was wrong about this"; "If I had to start over, I'd do this." Deliver them in the calm register, not the loud one. Never open on urgency or a countdown; the viewer is never rushed.

THE BEAT STRUCTURE (hold it through the whole script):
- HOOK (first 3 seconds of narration): stops the scroll with the specific claim.
- LEARNING OBJECTIVE (immediately after, finished inside the first 30 seconds, about the first 70 spoken words): one sentence saying what they will be able to do by the end, such as "By the end of this episode, you will be able to ...". Return it word for word in learning_objective.
- PROOF (the body): every claim carries a receipt. A number, a named tool, a documented before-and-after, a step the viewer can verify today.
- CHECKLIST (inside the body): 3 to 5 plain steps the viewer can repeat, spoken in order as step one, step two and so on. Return the same steps in checklist.
- CLOSE (the last 5 seconds): ONE question for the comments, specific to this episode and answerable from the viewer's own work, and nothing after it. Say the word comments in the last spoken sentence, as in: Tell me in the comments, then the question; the Script Gate holds the episode otherwise. Never ask the viewer to like or subscribe and never point to an audit, a download or a link; the brand does not beg.

Pick the ONE best-fit proven format for this topic and shape the whole script around it:
- LISTICLE: "N things / N moves / N mistakes" - concrete, countable, skimmable. Best for tools, tactics, errors.
- NEGATIVE / STOP: "Stop doing X" or "X is quietly costing you Y" - names a costly default behavior and its price.
- TUTORIAL: "How to do X" - a real, followable method with the payoff stated up front.
- CONTRARIAN / REFRAME: "Everyone believes X. Here is why the opposite is true." - overturns a common assumption.
- RECEIPT / STORY: one concrete before-to-after, with specific numbers doing the persuading.

Choose a PRIMARY KEYWORD (2-4 words) that a worried professional would actually type into YouTube search for this topic. Weave it naturally into the title and into the first sentence of the description. Never keyword-stuff.

FRAME OUTCOMES, NOT TOPICS. Every section connects to what the viewer GAINS or AVOIDS - the transformation, not the subject.

For the given Topic, produce:

1. title - under 60 characters, containing the primary keyword, specific and intriguing without clickbait, in the calm brand voice.

2. script - a long-form spoken narration of 1200-2000 words, target 1600. Hard floor 1200 words. Single narrator, natural spoken rhythm, no on-screen directions or headings. Structure for retention: the hook above in the first 10-15 seconds and the learning objective inside the first 30; then 8 to 12 distinct sections, each making one clear point backed by a concrete example, a number, a mini-story, or a proof point, with smooth spoken transitions that re-hook attention; the 3 to 5 step checklist, spoken inside one of those sections; at least one specific action the viewer can take today; and a calm, resonant close that lands the core idea and ends on the one comment-worthy question. Depth, not padding.

3. description - 2 to 3 sentences on the video's value, leading with the primary keyword. No link, no audit and no subscribe line. Leave the checklist out; the pipeline writes it into the description from the checklist field.

4. broll - an array of 8 to 12 short visual search phrases (2-4 words each), one per major section of the script, IN ORDER. These are CUTAWAYS over a presenter, not the main visual. Terrance is on screen for the episode and these cover only the beats that need an illustration. Name the thing being illustrated: a concrete object, screen, document or place, never a person standing in for him. No generic office workers, no anonymous professionals at desks, no handshakes. If a beat needs no illustration, name a neutral object rather than a person.

5. learning_objective - the learning objective sentence exactly as the script speaks it, character for character.

6. checklist - an array of 3 to 5 steps, each a short plain sentence the viewer can repeat, in the order the script speaks them, with no number or bullet in front.

Return ONLY a valid JSON object, no markdown fences, no commentary, in exactly this shape: {"title": "...", "script": "...", "description": "...", "broll": ["...", "..."], "learning_objective": "...", "checklist": ["...", "...", "..."]}`;
}

// DEVON grounding, ruled by Tee 15 Sep 2026 on an inline card: retrieval from
// his own record plus the exemplars of his edits, both folded onto the row by
// DEVON Recall: Merge. Either can be empty; the brand prompt above stands alone.
if (row.devonRecall) {
  system += '\n\n=== FROM DEVON: TEE\'S OWN RECORD, RETRIEVED FOR THIS TOPIC ===\nThese are Tee\'s rulings, notes and lessons. Obey them where they apply and never contradict them. Never present them as public facts and never cite them as sources.\n' + row.devonRecall;
}
if (row.devonExemplars) {
  system += '\n\n=== HOW TEE EDITS MACHINE DRAFTS (' + row.devonExemplarCount + ' exemplar(s)) ===\nEach pair shows how a machine draft opened and how Tee rewrote it. Write the way the rewrite reads, not the way the draft reads.\n' + row.devonExemplars;
}

return [{
  json: {
    airtableId: row.id,
    devonRecallNote: row.devonRecallNote || '',
    body: {
      model: "claude-sonnet-5",
      max_tokens: 6000,
      system: system,
      messages: [{ role: "user", content: "Topic: " + topic }]
    }
  }
}];

const resp = $json;
if (resp?.stop_reason === 'max_tokens' || resp?.choices?.[0]?.finish_reason === 'length') {
  throw new Error('Script truncated at the token ceiling. Raise MAX_TOKENS in Token Budget: Script.');
}
let text = resp?.choices?.[0]?.message?.content ?? resp?.content?.[0]?.text ?? '';

if (!text) {
  throw new Error('No text in the model response: ' + JSON.stringify(resp).slice(0, 300));
}

text = text.replace(/```json/gi, '```');
const start = text.indexOf('{');
const end = text.lastIndexOf('}');
if (start === -1 || end === -1) {
  throw new Error('No JSON object in the model output. Got: ' + text.slice(0, 300));
}

let parsed;
try {
  parsed = JSON.parse(text.slice(start, end + 1));
} catch (e) {
  throw new Error('JSON.parse failed: ' + e.message + ' | Got: ' + text.slice(0, 300));
}

const recordId = $('One Idea at a Time').first().json.id;

return [{
  json: {
    recordId,
    title: parsed.title ?? parsed.video_title ?? '',
    script: parsed.script ?? '',
    description: parsed.description ?? '',
    tags: Array.isArray(parsed.tags) ? parsed.tags.join(', ') : (parsed.tags ?? ''),
    broll: Array.isArray(parsed.broll) ? parsed.broll.map(s => String(s).trim()).filter(Boolean).join(', ') : '',
    learningObjective: typeof parsed.learning_objective === 'string' ? parsed.learning_objective.trim() : '',
    checklist: Array.isArray(parsed.checklist) ? parsed.checklist.filter(s => typeof s === 'string').map(s => s.trim()).filter(Boolean) : [],
  }
}];

// Build Movie v9 - PRESENTER LAYER. Matched b-roll + presenter segments. Cold open.
//
// PRESENTER-LED (Quality Law rev2, ruled by Tee 2026-09-30): the avatar segments
// from the Presenter Clips lane (Plan Presenter Segments -> HeyGen/Runway batch)
// are the on-camera identity; b-roll is the bridge. Every presenter clip must be
// share-verified in at_tqo_presenter_clips BEFORE inclusion - the moov-atom
// failure lesson: an owner-only file downloads as an HTML sign-in page and the
// worker writes the HTML into the clip, and ffmpeg refuses it.
//
// v8 history below, retained:
//
// POOL RETIRED - 10 Aug 2026.
//
// All 21 clips in the pool folder were reviewed frame by frame. Every one is
// abstract texture: aerial city at night, rain on glass with bokeh, smoke,
// silk folds, ocean surface, a spiral staircase, a flat orange field. Four are
// close to solid black and would read as a dead frame in an episode.
//
// Not one contains a person, a desk, a screen, a keyboard or an office. So no
// clip in the pool matches any keyword 'Plan B-Roll Segments' produces, and the
// pool was inserting unrelated mood texture on any beat Pexels could not fill.
//
// POOL_SHARED false restores the original fallback: hold the previous clip. That
// is the designed behaviour and heldClips already reports how often it happens.
// Watch that number. If it climbs, the fix is better Pexels queries or real
// owned footage, NOT switching the pool back on.
//
// Re-enable only when the folder contains footage about the subject - screen
// recordings of the workflow canvas, Airtable views, the render queue, the
// Human Review tick. Those are tracked in the B-Roll Library table
// (tbl2pr5GLeeUJK1rr) and every row there carries a Verified flag meaning share
// permission AND file size were both checked.
//
// The POOL array below is left in place, unused, so re-enabling is one boolean
// rather than an archaeology exercise. Do not add to it. Add to the folder and
// the library table instead.
//
// History worth keeping, because this failed silently for a long time.
// Render uYn0b5SzQwGflxwh died with:
//   ffmpeg failed: moov atom not found
//   Error opening input file /data/work/.../clip9.mp4
// clip9 came from POOL. Those Drive files were owner-only, so an
// unauthenticated download returned an HTML sign-in page, the worker wrote the
// HTML to clip9.mp4, and ffmpeg refused it. The voice mp3 uses the same host
// and worked only because 'Make Audio Public' shares that one file first.
//
// Drive also serves a scan interstitial above roughly 25MB, which produces the
// identical symptom. Both share permission and file size have to be right.
//
// If moov atom errors come back, check those two things first before assuming
// the render worker is at fault. It was never the worker.
const POOL_SHARED = false;

const W = 1920, H = 1080;

// INTRO AND END CARDS REMOVED - 9 Aug 2026.
//
// Both bumpers lived on the ops box and were brand-agnostic: the same 3.5s
// intro and 16s end card played on NCO Forge as on The Quiet Operator. Once
// both brands went daily that was simply wrong, and neither card matched the
// register of either show. A cold open suits writing this restrained better
// than a bumper does, and 16 seconds of card at the end is 16 seconds of a
// viewer deciding to leave.
//
// LEAD_PAD replaces INTRO_DUR everywhere it was used, so the timing maths
// downstream is unchanged - it is just a much smaller number now. It exists so
// the first syllable is not clipped by the encoder; it is silence, not a card.
//
// To bring cards back, set LEAD_PAD to the intro duration and re-add the two
// video elements at the bottom of the scene. Make them brand-aware off
// Show Context: Render if you do - do not go back to one file for both shows.
const LEAD_PAD = 0.5;

const segs = $('Plan B-Roll Segments').all();
const px   = $('Pexels Search').all();
const POOL = [
  "https://drive.usercontent.google.com/download?id=1ljdeliylCdqu81Mbyar4lwknc35dbEAJ&export=download&confirm=t",
  "https://drive.usercontent.google.com/download?id=1FrtF4HrT3JvvllCXMRU96u_7238ug8jn&export=download&confirm=t",
  "https://drive.usercontent.google.com/download?id=1lJMu49tUqXNx1xBMRBDVB4Aa4zdvTyK9&export=download&confirm=t",
  "https://drive.usercontent.google.com/download?id=1P2OZjX92rl8DH1-D_zXbGQuXu4qAwSPM&export=download&confirm=t",
  "https://drive.usercontent.google.com/download?id=1d-f-HmzVeFyodq1tWJKeZmCmW4Yp8QRd&export=download&confirm=t",
  "https://drive.usercontent.google.com/download?id=10VMbspxabGdXEaaxksmFyyNLX0WLMfzb&export=download&confirm=t",
  "https://drive.usercontent.google.com/download?id=1Kt3fiWaSmYFDhFFgiMwYROdaUlISExsD&export=download&confirm=t",
  "https://drive.usercontent.google.com/download?id=10j_YmgIs3zNSwkz2r19jPC0YkTjkRJ77&export=download&confirm=t",
  "https://drive.usercontent.google.com/download?id=1Jgy_6SLa0BC65BIcE1papnWQwvOEwxVA&export=download&confirm=t",
  "https://drive.usercontent.google.com/download?id=11z7GEcmVie4BUxgeJ1oJxgs9z--H_bwe&export=download&confirm=t"
];

// Every usable file from a Pexels response, best-fit width first, one per video.
// The old version read videos[0] only and threw away two clips it had already
// paid for on the same call. per_page is now 15, so this list is much longer
// and the recency filter below has real room to work.
function candidates(resp){
  const vids = (resp && Array.isArray(resp.videos)) ? resp.videos : [];
  const out = [];
  for (const v of vids) {
    const files = (v.video_files || []).filter(f => (f.file_type || '').includes('mp4') && f.width);
    if (!files.length) continue;
    files.sort((a, b) => (b.width || 0) - (a.width || 0));
    const pick = files.find(f => f.width && f.width <= 3840) || files[files.length - 1];
    if (pick && pick.link) out.push(pick.link);
  }
  return out;
}

let poolIdx = 0, lastSrc = null, poolUsed = 0, heldClips = 0;
const recent = [];            // short memory so a clip does not reappear immediately
const usedAll = new Set();    // benchmark visual rule: no clip reuse within an episode
const broll = [];

for (let i = 0; i < segs.length; i++) {
  const s = segs[i].json;
  const cands = candidates(px[i] && px[i].json);

  // Pexels first: those clips were chosen against the narration for this beat.
  // Prefer one unused in the last three segments, then one not equal to the
  // previous, then anything.
  let src = cands.find(c => !usedAll.has(c))
         || cands.find(c => !recent.includes(c))
         || cands.find(c => c !== lastSrc)
         || cands[0]
         || null;

  if (!src) {
    if (POOL_SHARED) { src = POOL[poolIdx % POOL.length]; poolIdx++; poolUsed++; }
    else { src = lastSrc; heldClips++; }
  }
  if (!src) continue;                          // nothing at all for the opening segment

  lastSrc = src;
  recent.push(src);
  if (recent.length > 3) recent.shift();
  usedAll.add(src);

  broll.push({ type: "video", src, start: LEAD_PAD + s.start, duration: s.duration, muted: true });
}

const first = segs[0].json;
const voiceUrl = "https://drive.usercontent.google.com/download?id=" + first.uploadId + "&export=download&confirm=t";
const MUSIC = [
  "http://150.136.200.85/music/track1.mp3","http://150.136.200.85/music/track2.mp3",
  "http://150.136.200.85/music/track3.mp3","http://150.136.200.85/music/track4.mp3",
  "http://150.136.200.85/music/track5.mp3",
];
let hash = 0; for (const ch of String(first.uploadId)) hash = (hash * 31 + ch.charCodeAt(0)) >>> 0;
const musicUrl = MUSIC[hash % MUSIC.length];

// --- PRESENTER LAYER (v9) ---
// Plan Presenter Segments emits the ordered presenter/broll timeline and the
// shot list for the HeyGen/Runway batch. Clips live in the Presenter Clips
// Drive folder (1SyqzTVQYxsGXol4N1vBQfI4FVC1cVeK8), one per segment,
// named presenter-{rowId}-{segmentIndex}.mp4, voice already baked in.
//
// Clip URLs come from the shot-list writer's share results carried on the item
// (presenterClips: [{segmentIndex, publicUrl, duration}]). A required presenter
// segment with no verified clip REFUSES to render: a presenter-led episode
// shipping without its presenter is a quality law failure, not a degraded mode.
const pres = $json.presenterClips || [];
const requiredMissing = [];
for (const seg of pres) {
  if (!seg.publicUrl || !seg.shareVerified) {
    requiredMissing.push('segment ' + seg.segmentIndex + ' (' + (seg.file || 'unnamed') + '): ' + (!seg.publicUrl ? 'no clip' : 'not share-verified'));
  }
}
if (requiredMissing.length) {
  throw new Error('PRESENTER REFUSAL - missing or unverified presenter clips: ' + requiredMissing.join('; ') + '. Fill the Presenter Clips folder and set share_verified in at_tqo_presenter_clips, then re-run.');
}

// Presenter elements render ABOVE b-roll (inserted after the b-roll spread).
// Voice: presenter clips carry the ElevenLabs voice baked in, so when any
// presenter clip exists the single audio element points at the FIRST presenter
// clip's audio track... but the worker historically kept ONE audio element and
// one audio SOURCE per element. Safety design (no probe risk): keep the voice
// mp3 audio element as-is and lay presenter clips MUTED. The voice timing is
// unchanged and nothing double-speaks. If the adapter later proves multi-source
// audio, flip presenterAudioFirst to true to take audio from the presenter clip
// instead of the mp3 (the mp3 then becomes the fallback voice track).
const PRESENTER_AUDIO_FIRST = false;
const presenterElements = pres.map(seg => ({
  type: "video",
  src: seg.publicUrl,
  start: LEAD_PAD + seg.start,
  duration: seg.duration,
  muted: true
}));

const lastSeg = segs[segs.length - 1].json;
const bodyEnd = LEAD_PAD + (lastSeg.start + lastSeg.duration);   // now the true end of the video


function srtTime(value) {
  const ms = Math.max(0, Math.round(Number(value || 0) * 1000));
  const h = String(Math.floor(ms / 3600000)).padStart(2, '0');
  const m = String(Math.floor((ms % 3600000) / 60000)).padStart(2, '0');
  const s = String(Math.floor((ms % 60000) / 1000)).padStart(2, '0');
  const x = String(ms % 1000).padStart(3, '0');
  return h + ':' + m + ':' + s + ',' + x;
}
const srt = segs.map((item, index) => {
  const segment = item.json;
  const start = LEAD_PAD + Number(segment.start || 0);
  const end = start + Number(segment.duration || 0);
  const narration = String(segment.narration || '').trim();
  if (!narration) return '';
  return (index + 1) + '\n' + srtTime(start) + ' --> ' + srtTime(end) + '\n' + narration + '\n';
}).filter(Boolean).join('\n');
if (!srt.trim()) throw new Error('Subtitle SRT is empty');

const movie = {
  resolution: "custom", width: W, height: H,
  scenes: [{ elements: [
    ...broll,
    ...presenterElements,
    // ONE AUDIO ELEMENT ONLY - 15 Sep 2026. The VPS adapter at 172.16.2.1:8081
    // keeps a single audio element and it was the music: execution 46 carried
    // the bed and no narration, probe A (voice alone) carried the clone voice,
    // probe B (music first, voice second) carried music only. The bed comes
    // back ducked under the voice through our own worker's duck_mix job in the
    // presenter build. musicUrl is still computed above so that step can use it.
    { type: "audio", src: voiceUrl, start: LEAD_PAD, volume: 1.0 }
    // NO BURNED CAPTIONS ON LONG FORM - ruled by Tee 15 Sep 2026 on an inline
    // card: Shorts carry burned captions, long form ships clean with the SRT
    // uploaded as a YouTube caption track and numbers shown as on-screen
    // callouts. The SRT is still built above and returned below so Mark Ready
    // saves it on the row for the publish lane. Before this ruling the element
    // { type: "subtitles", srt, settings: {...} } sat here.
  ]}]
};

const ROW = $('Presenter: Attach Clips').first().json || {};
const TITLE = (ROW.videoTitle || ROW.title || ('episode-' + (ROW.rowId ?? 'untitled')));
return [{ json: { j2vBody: movie, clipCount: broll.length, presenterCount: pres.length, presenterAudioFirst: PRESENTER_AUDIO_FIRST,
                  poolUsed, heldClips, poolEnabled: POOL_SHARED,
                  leadPad: LEAD_PAD, runtimeSec: Math.round(bodyEnd), srt, rowId: ROW.rowId, videoTitle: TITLE } }];

// v7. Validates the atomizer output against its own primitive map.
//
// The point of the primitive model is that an asset has to have a reason to
// exist. That is only true if something checks. An asset citing a primitive
// that is missing, or one that scored below the floor, is exactly the
// low-quality duplication the model was introduced to prevent, so it is
// dropped here rather than published and regretted.
//
// Label contract: OS 30 gate 4 greps this block for the literal strings
// 'SHORT SCRIPT 1', 'LINKEDIN 1', 'X THREAD 1' and 'THUMBNAIL TEXT'. Do not
// rename those prefixes without changing the gate in the same pass.
const STRENGTH_FLOOR = 65;

const out = $json;
if ((out.stop_reason === 'max_tokens' || out.choices?.[0]?.finish_reason === 'length')) throw new Error('Packaging truncated at max_tokens. Raise MAX_TOKENS in Token Budget: Packaging.');
let raw = out.choices?.[0]?.message ? String(out.choices[0].message.content ?? '') : (out.content || []).filter(c => c.type === 'text').map(c => c.text).join('');
raw = String(raw).trim().replace(/^```(json)?/i, '').replace(/```$/, '').trim();
let p;
try { p = JSON.parse(raw); }
catch (e) {
  const s = raw.indexOf('{'), en = raw.lastIndexOf('}');
  if (s === -1 || en === -1) throw new Error('Packaging was not JSON. Start: ' + raw.slice(0, 200));
  p = JSON.parse(raw.slice(s, en + 1));
}

const prims = Array.isArray(p.primitives) ? p.primitives : [];
const byId = {};
prims.forEach(x => { if (x && x.id) byId[String(x.id)] = x; });

const dropped = [];
function keep(a, label) {
  if (!a) return false;
  const id = String(a.from || '');
  if (!id) { dropped.push(label + ': no primitive cited'); return false; }
  const pr = byId[id];
  if (!pr) { dropped.push(label + ': cites ' + id + ', which is not in the primitive map'); return false; }
  const s = Number(pr.strength || 0);
