// Semantic scene director. Was: fixed 18s slices, keywords distributed by
// arithmetic. 18 seconds on one stock clip reads as filler, and a keyword chosen
// by index has no relationship to what is being said over it.
//
// Now: scenes break on sentence boundaries, run 5-12s scaled to how long the
// narration actually takes, and each keyword is chosen by term overlap with the
// words spoken over that scene. Total duration still tracks the narration.
//
// Segment count is capped so a long episode cannot exhaust the Pexels quota.

const ROW = $('Process Each Video');
const UP  = $('Upload MP3');
const WPM = 150;
const MIN_SEC = 5, MAX_SEC = 12, TARGET_SEC = 8, MAX_SEGMENTS = 45;

const fields = ROW.item.json.fields || {};
const script = String(fields['Script'] || '');
const allWords = script.trim() ? script.trim().split(/\s+/).length : 300;
const estSecs = Math.max(60, Math.round((allWords / WPM) * 60));

let kws = String(fields['Broll Keywords'] || '').split(',').map(s => s.trim()).filter(Boolean);
if (!kws.length) {
  kws = ['professional working late laptop','office desk documents','hands typing keyboard',
         'man thinking by window','meeting room discussion','city commute morning',
         'coffee cup desk work','walking office corridor'];
}

// Break on sentence boundaries, then group into scenes near the target length.
const sentences = script.replace(/\s+/g, ' ').match(/[^.!?]+[.!?]+|[^.!?]+$/g) || [script];
const secsFor = (txt) => (txt.trim().split(/\s+/).filter(Boolean).length / WPM) * 60;

const scenes = [];
let buf = '', bufSecs = 0;
for (const s of sentences) {
  const ss = secsFor(s);
  if (bufSecs > 0 && bufSecs + ss > MAX_SEC) { scenes.push({ text: buf.trim(), secs: bufSecs }); buf = ''; bufSecs = 0; }
  buf += ' ' + s; bufSecs += ss;
  if (bufSecs >= TARGET_SEC) { scenes.push({ text: buf.trim(), secs: bufSecs }); buf = ''; bufSecs = 0; }
}
if (buf.trim()) {
  if (scenes.length && bufSecs < MIN_SEC) { scenes[scenes.length - 1].text += ' ' + buf.trim(); scenes[scenes.length - 1].secs += bufSecs; }
  else scenes.push({ text: buf.trim(), secs: Math.max(bufSecs, MIN_SEC) });
}
if (!scenes.length) scenes.push({ text: script.slice(0, 400), secs: estSecs });

// Cap without dropping narration: merge neighbours until under the ceiling.
while (scenes.length > MAX_SEGMENTS) {
  let mi = 0, ms = Infinity;
  for (let i = 0; i < scenes.length - 1; i++) {
    const c = scenes[i].secs + scenes[i + 1].secs;
    if (c < ms) { ms = c; mi = i; }
  }
  scenes[mi].text += ' ' + scenes[mi + 1].text;
  scenes[mi].secs += scenes[mi + 1].secs;
  scenes.splice(mi + 1, 1);
}

// Normalise so the visual track matches the narration length.
const rawTotal = scenes.reduce((a, s) => a + s.secs, 0) || 1;
const scale = estSecs / rawTotal;

const STOP = new Set(['the','a','an','and','or','but','is','are','was','were','to','of','in','on','for','with','that','this','it','you','your','they','their','be','as','at','by','from','not','have','has','had','do','does','did','will','would','can','could','what','when','how','why','who','if','so','than','then','there','here','more','most','one','out','up','about','into','over','after','before','because','just','like','only','also','very','much','make','makes','made','get','gets','got']);
const terms = (t) => new Set(String(t).toLowerCase().replace(/[^a-z0-9\s]/g, ' ').split(/\s+/).filter(w => w.length > 3 && !STOP.has(w)));
const kwTerms = kws.map(k => ({ kw: k, t: terms(k) }));

const out = [];
let cursor = 0, lastKw = null;
scenes.forEach((sc, i) => {
  const dur = Math.max(MIN_SEC, Math.min(MAX_SEC, Math.round(sc.secs * scale * 10) / 10));
  const st = terms(sc.text);

  // Score each keyword by term overlap with what is actually said over this scene.
  let best = null, bestScore = -1;
  for (const k of kwTerms) {
    let score = 0;
    for (const w of k.t) if (st.has(w)) score += 2;
    for (const w of k.t) for (const sw of st) if (sw.startsWith(w.slice(0, 4))) { score += 0.25; break; }
    if (k.kw === lastKw) score -= 1.5;  // avoid the same clip twice running
    if (score > bestScore) { bestScore = score; best = k.kw; }
  }
  // No real overlap - rotate rather than pretend a match exists.
  const query = bestScore > 0 ? best : kws[i % kws.length];
  lastKw = query;

  out.push({ json: {
    segIndex: i,
    start: Math.round(cursor * 10) / 10,
    duration: dur,
    query,
    matchScore: Math.round(bestScore * 100) / 100,
    matched: bestScore > 0,
    narration: sc.text,
    uploadId: UP.item.json.id,
    videoTitle: String(fields['Video Title'] || 'The Quiet Operator')
  } });
