// Stale-claim reaper (wired 8 Aug 2026; publish/render split + retry-cap 12 Aug 2026).
//
// Why this exists: on 27 June a render run died mid-flight leaving one row in
// Rendering. 'Anything Still Rendering?' found it every cycle, 'IF Coast Clear'
// closed, and the render lane produced nothing for six weeks while every
// execution reported success. A claim with no owner is a dead system holding the
// door shut.
//
// Releases claims older than staleClaimHours:
//   - PUBLISH claim (System Status 'publishing...') -> Status 'Ready'. Already
//     rendered and maybe already live, so it re-enters the publish lane, NOT the
//     render lane, to avoid a re-render and double-post. Render Attempts is left
//     untouched (publishing does not re-bill TTS).
//   - RENDER claim (Status 'Rendering' / System Status 'claimed:...') -> normally
//     Status 'Queued' to retry. But an orphaned render claim re-bills full
//     ElevenLabs TTS every retry, so it shares the same cap as an in-execution
//     failure: increment 'Render Attempts', and at the cap park it at 'Blocked'
//     instead of Queued. Reset to 0 on a successful render (Mark Ready + Save URL).
// Runs on a side branch so a reaper failure can never take the render lane with it.
const MAX_RENDER_ATTEMPTS = 3;

const ctx = $('Show Context: Render').first().json;
const recs = ($json.records || []);
if (!recs.length) return [];

const stamp = new Date().toISOString();

const records = recs.slice(0, 10).map(r => {
  const f = r.fields || {};
  const sys = String(f['System Status'] || '');
  const wasPublishing = sys.slice(0, 10) === 'publishing';

  if (wasPublishing) {
    const note = 'Auto-released by the stale-claim reaper at ' + stamp +
      '. It was a PUBLISH claim (already rendered, possibly already live), so it ' +
      're-enters the publish lane as Ready, not the render lane, to avoid a re-render and double-post.';
    return { id: r.id, fields: { 'Status': 'Ready', 'System Status': '', 'Last Feedback': note } };
  }

  // Render claim: count this orphaned attempt against the same cap as an
  // in-execution failure so a permanently-stuck row stops re-billing TTS.
  const prev = Number(f['Render Attempts'] ?? 0) || 0;
  const attempts = prev + 1;
  const blocked = attempts >= MAX_RENDER_ATTEMPTS;
  const target = blocked ? 'Blocked' : 'Queued';
  const note = blocked
    ? ('Reaped after a stranded render (attempt ' + attempts + ' of ' + MAX_RENDER_ATTEMPTS +
       ') at ' + stamp + '. Parked at Blocked: it kept getting claimed and never finishing, ' +
       're-billing TTS each time. Fix the render worker or the clip, then set Status back to ' +
       'Queued and Render Attempts to 0 by hand.')
    : ('Auto-released by the stale-claim reaper at ' + stamp + '. Attempt ' + attempts + ' of ' +
       MAX_RENDER_ATTEMPTS + '. A previous run claimed this row and never finished, so it went ' +
       'back to Queued. Reaped repeatedly means the render itself is failing, not the claim.');
  return { id: r.id, fields: { 'Status': target, 'System Status': '', 'Render Attempts': attempts, 'Last Feedback': note } };
});

return [{ json: {
  tableId: ctx.tableId,
  tableRef: ctx.tableRef,
  released: recs.length,
  releasedTopics: recs.map(r => (r.fields || {}).Topic || r.id),
  body: { typecast: true, records }
} }];

