  ? 'THE STANDARD: one memorable leadership principle.'
  : 'THE QUIET MOVE: one usable action, never a generic CTA.';

const system = [
  'You distil a finished video script into a Content Manifest for ' + ctx.channel + '.',
  'You add nothing. Every field is extracted from the script as written.',
  'If the script genuinely lacks something, return an empty string. Never invent.',
  'This channel has a signature framework: ' + sig,
  'Every episode closes on ' + close,
  '',
  'Return ONLY valid JSON, no fences, exactly these keys:',
  '{',
  '"thesis":"the single argument in one sentence",',
  '"hook":"the opening claim, verbatim from the script",',
  '"stakes":"why the viewer should care, one sentence",',
  '"proof_points":["concrete evidence, numbers, named examples"],',
  '"stories":["self-contained anecdotes with a beginning and an end"],',
  '"quotables":["5-8 lines that stand alone out of context"],',
  '"contrarian_claims":["where this disagrees with the common view"],',
  '"payoff":"what the viewer leaves with",',
  '"signature_framework":"the five answers if present, else empty",',
  '"closing_move":"the closing action or principle, verbatim",',
  '"visual_metaphors":["images the argument suggests"],',
  '"short_candidates":[{"angle":"distinct angle","hook_line":"spoken opener","source_quote":"verbatim from script","why":"why this stands alone"}],',
  '"primary_keyword":"one search phrase",',
  '"claims_needing_check":["any statistic, date or attribution a viewer could dispute"]',
  '}'
].join('\n');

const body = {
  model: 'claude-sonnet-5',
  max_tokens: 4000,
  system: system,
  messages: [{ role: 'user', content: 'Title: ' + title + '\n\nFull script:\n' + script }]
};
return [{ json: { airtableId: airtableId, claudeBody: body } }];

// Degrades safely. A missing manifest must not stop the episode; it only means
// downstream agents fall back to reading the script directly, and QC says so.
const airtableId = $('Build Manifest Prompt').first().json.airtableId;
const out = $json || {};

function empty(reason) {
  return [{ json: { airtableId, manifest: null, manifestJson: '', manifestError: reason } }];
}

if ((out.stop_reason === 'max_tokens' || out.choices?.[0]?.finish_reason === 'length')) return empty('Manifest truncated at max_tokens.');
let raw = out.choices?.[0]?.message ? String(out.choices[0].message.content ?? '') : (out.content || []).filter(c => c.type === 'text').map(c => c.text).join('');
if (!raw.trim()) return empty('Manifest agent returned nothing - check the Anthropic credential on Write Manifest (Claude).');
raw = String(raw).trim().replace(/^```(json)?/i, '').replace(/```$/, '').trim();

let m;
try { m = JSON.parse(raw); }
catch (e) {
  const s = raw.indexOf('{'), en = raw.lastIndexOf('}');
  if (s === -1 || en === -1) return empty('Manifest was not JSON. Start: ' + raw.slice(0, 160));
  try { m = JSON.parse(raw.slice(s, en + 1)); } catch (e2) { return empty('Manifest JSON unparseable.'); }
}

return [{ json: {
  airtableId,
  manifest: m,
  manifestJson: JSON.stringify(m, null, 2),
  manifestError: ''
} }];

// Fails closed on both verdicts. If QC cannot run, the episode is HOLD and the
// batch is ungraded, which gate 10 treats as a block. Never an unchecked SHIP.
const SHIP_AT = 80;
const ctx = $('Show Context: Publish').first().json;
const row = $('One Row at a Time').first().json;
const f = row.fields || row;
const airtableId = $('Build QC Prompt').first().json.airtableId;
const prior = String(f['Score History'] || '');
const stamp = new Date().toISOString();

function hold(reason) {
  return [{ json: { airtableId, qcVerdict: 'HOLD', qcScore: 0,
    packagingGrade: null, packagingGradeReport: 'Not graded. ' + reason,
    qcFindings: 'QC could not run at ' + stamp + '. ' + reason +
      '\n\nNothing auto-ships unchecked. Fix the cause, or set QC Verdict to WAIVED by hand if this is a deliberate call.',
    scoreHistory: (prior ? prior + '\n' : '') + stamp + ' | QC UNAVAILABLE | ' + reason } }];
}

const out = $json || {};
if ((out.stop_reason === 'max_tokens' || out.choices?.[0]?.finish_reason === 'length')) return hold('QC response truncated at max_tokens.');
let raw = out.choices?.[0]?.message ? String(out.choices[0].message.content ?? '') : (out.content || []).filter(c => c.type === 'text').map(c => c.text).join('');
if (!raw.trim()) return hold('QC returned nothing. Check the Anthropic credential on Run QC (Claude).');
raw = String(raw).trim().replace(/^```(json)?/i, '').replace(/```$/, '').trim();

let q;
try { q = JSON.parse(raw); }
catch (e) {
  const s = raw.indexOf('{'), en = raw.lastIndexOf('}');
  if (s === -1 || en === -1) return hold('QC did not return JSON.');
  try { q = JSON.parse(raw.slice(s, en + 1)); } catch (e2) { return hold('QC JSON unparseable.'); }
}

const sc = q.scores || {};
const total = Number(q.total) || Object.values(sc).reduce((a, b) => a + (Number(b) || 0), 0);
const blockers = Array.isArray(q.blockers) ? q.blockers.filter(Boolean) : [];
const findings = Array.isArray(q.findings) ? q.findings : [];
const verdict = (blockers.length === 0 && total >= SHIP_AT) ? 'SHIP' : 'HOLD';

const bScore = Number(q.batch_score);
const bAssets = Array.isArray(q.batch_assets) ? q.batch_assets : [];
const gradeReport = [
  'PACKAGING GRADE ' + (isFinite(bScore) ? bScore.toFixed(1) : '?') + '/10 (hook weighted 50%)',
  q.batch_weakest ? 'WEAKEST: ' + q.batch_weakest : '',
  ...bAssets.map(a => '  ' + String(a.asset || '?').padEnd(16) + ' hook ' + (a.hook ?? '?') + '  total ' + (a.total ?? '?') + '\n      fix: ' + String(a.fix || '')),
  ...(Array.isArray(q.batch_notes) && q.batch_notes.length ? ['', 'BATCH:', ...q.batch_notes.map(n => '  - ' + n)] : []),
  ...(Array.isArray(q.batch_fixes) && q.batch_fixes.length ? ['', 'TOP FIXES:', ...q.batch_fixes.map(n => '  - ' + n)] : [])
].filter(Boolean).join('\n');

const report = [
  'QC ' + verdict + ' - ' + total + '/100 (ship threshold ' + SHIP_AT + ') at ' + stamp,
  ctx.channel + ' | ' + (f.Show || 'unassigned show') + ' S' + (f.Season || '?') + 'E' + (f.Episode || '?'),
  '',
  Object.entries(sc).map(([k, v]) => '  ' + k + ': ' + v).join('\n'),
  blockers.length ? '\nHARD BLOCKERS:\n' + blockers.map(b => '  - ' + b).join('\n') : '',
  findings.length ? '\nFINDINGS:\n' + findings.map(x =>
    '  - [' + (x.dimension || '?') + '] ' + (x.issue || '') + '\n      fix: ' + (x.fix || '')).join('\n') : '',
  q.strongest ? '\nSTRONGEST: ' + q.strongest : '',
  q.one_change ? 'ONE CHANGE THAT BUYS THE MOST: ' + q.one_change : '',
  '\n' + gradeReport
].filter(Boolean).join('\n');

return [{ json: {
  airtableId, qcVerdict: verdict, qcScore: total, qcFindings: report,
  packagingGrade: isFinite(bScore) ? bScore : null,
  packagingGradeReport: gradeReport,
  scoreHistory: (prior ? prior + '\n' : '') + stamp + ' | ' + total + '/100 ' + verdict +
    ' | batch ' + (isFinite(bScore) ? bScore.toFixed(1) : '?') + '/10' +
    ' | ' + Object.entries(sc).map(([k, v]) => k + ':' + v).join(' ') +
    (blockers.length ? ' | BLOCKED: ' + blockers.join('; ') : '')
} }];

// Asset Type is a closed vocabulary and the script writer's Idea filter matches
// it as an exact string, so a drifted spelling here would put a Short straight
// back into the long-form queue without anything erroring. The value below is a
// literal, so an unknown one can only mean this node was edited wrong. Fail loud.
const ASSET_TYPES = ['Flagship', 'Short'];
function assetType(v) {
  const raw = String(v == null ? '' : v).trim();
  const hit = ASSET_TYPES.filter(t => t.toLowerCase() === raw.toLowerCase())[0];
  if (!hit) throw new Error('Unknown Asset Type "' + raw + '". Allowed: ' + ASSET_TYPES.join(', '));
  return hit;
}

// Every flagship that clears the gate spawns its short-form scripts as child
// rows, linked back to the parent episode. A Short with no parent is just
// another orphan upload, which gate 9 exists to prevent.
//
// Since the atomizer, each short carries the content function it serves
// (CONFLICT, CONTRARIAN, STORY, RULE, QUESTION) and the primitive it was built
// from, so a short that underperforms can be traced to the idea rather than
// blamed on the edit.
const ctx = $('Show Context: Publish').first().json;
const row = $('One Row at a Time').first().json;
const f = row.fields || row;
const pk = $('Parse Packaging').first().json;
const parentId = String(f.id || pk.airtableId || '');

const shorts = Array.isArray(pk.shortScripts) ? pk.shortScripts : [];
if (!shorts.length) return [];

const isNCO = ctx.show === 'NCO';
const showForShort = isNCO ? 'Forge Rules' : String(f.Show || '');
const baseTitle = String(f['Video Title'] || f.Topic || '');

const records = shorts.map((s, i) => {
  const fn = String(s.function || '').toUpperCase();
  const script = [
    'HOOK (0:00-0:02)',
    'Spoken: ' + String(s.hook_spoken || ''),
    'On-screen: ' + String(s.hook_onscreen || ''),
    '',
    'BODY',
    String(s.body || ''),
    '',
    'CTA (final 3s)',
    String(s.cta || '')
  ].join('\n');

  const fields = {
    'Topic': baseTitle + ' - Short ' + (i + 1) + (fn ? ' [' + fn + ']' : '') + ': ' + String(s.angle || ''),
    'Idea': 'Derived from the flagship, content function ' + (fn || 'unclassified') +
            ', built from primitive ' + String(s.from || 'unknown') + '. Angle: ' + String(s.angle || '') +
            '. This must add a distinct angle, never repeat the episode; interchangeable derivatives are exactly what the platform penalises.',
    'Script': script,
    'Status': 'Idea',
    'Channel': ctx.channel,
    'Asset Type': assetType('Short'),
    'Parent Record': parentId,
    'Aspect Ratio': '9:16',
    'Season': f.Season,
    'Episode': f.Episode
  };
  if (showForShort) fields['Show'] = showForShort;
  return { fields };
});

return [{ json: {
  tableId: ctx.tableId,
  tableRef: ctx.tableRef,
  spawned: records.length,
  body: { typecast: true, records }
} }];

// OFFER ENGINE - decides what this episode naturally solves.
//
// Rule: match or stay silent. Attaching the Quiet Leverage to an episode
// about building agents does not sell a Quiet Leverage, it teaches the viewer that the
// CTA is noise. Below threshold this attaches nothing and the episode ships on
// the free tier alone, which is a deliberate outcome and not a failure.

const THRESHOLD = 45;
const ctx = $('Show Context: Publish').first().json;
const row = $('One Row at a Time').first().json;
const f = row.fields || row;
const mfNode = $('Parse Manifest').first().json;

const offers = ($json.records || []).map(r => ({ id: r.id, ...(r.fields || {}) }));

// Everything the episode is about, in one bag of text to score against.
const mfObj = mfNode.manifest || {};
const haystack = [
  String(f.Topic || ''), String(f['Video Title'] || ''), String(f.Idea || ''),
  mfObj.thesis || '', mfObj.stakes || '', mfObj.payoff || '',
  (mfObj.proof_points || []).join(' '), (mfObj.quotables || []).join(' '),
  (mfObj.contrarian_claims || []).join(' '), mfObj.primary_keyword || '',
  String(f.Script || '').slice(0, 4000)
].join(' ').toLowerCase();

const pillar = String(f['Content Pillar'] || '').trim();
const show = String(f.Show || '');

function scoreOffer(o) {
  let score = 0;
  const why = [];

  const pillars = Array.isArray(o['Trigger Pillars']) ? o['Trigger Pillars'] : [];
  if (pillars.length === 0) { score += 10; why.push('offer is pillar-agnostic (+10)'); }
  else if (pillar && pillars.includes(pillar)) { score += 30; why.push('pillar "' + pillar + '" is a declared trigger (+30)'); }
  else { why.push('pillar "' + (pillar || 'unset') + '" not among triggers (+0)'); }

  const kws = String(o['Trigger Keywords'] || '').split(',').map(s => s.trim().toLowerCase()).filter(Boolean);
  let hits = 0; const hitList = [];
  for (const k of kws) if (k.length > 2 && haystack.includes(k)) { hits++; hitList.push(k); }
  const kwScore = Math.min(40, hits * 8);
  score += kwScore;
  if (hits) why.push('matched ' + hits + ' trigger phrase' + (hits > 1 ? 's' : '') + ' [' + hitList.slice(0, 6).join(', ') + '] (+' + kwScore + ')');

  const STOP = new Set(['the','a','an','and','or','but','is','are','was','to','of','in','on','for','with','that','this','it','you','your','they','their','be','as','at','by','from','not','have','has','do','does','will','would','can','what','when','how','why','who','if','so','than','then','there','more','most','one','out','about','into','over','after','before','because','just','like','only','also','very','much','make','get','which','while','them','were','been','need','want','know','right','now','yourself']);
  const terms = t => [...new Set(String(t).toLowerCase().replace(/[^a-z0-9\s]/g, ' ').split(/\s+/).filter(w => w.length > 3 && !STOP.has(w)))];
  const promiseTerms = terms(String(o.Promise || '') + ' ' + String(o['Problem Solved'] || ''));
  let pHits = 0;
  for (const t of promiseTerms) if (haystack.includes(t)) pHits++;
  const pScore = promiseTerms.length ? Math.min(20, Math.round((pHits / promiseTerms.length) * 20)) : 0;
  score += pScore;
  if (pScore) why.push('promise overlap ' + pHits + '/' + promiseTerms.length + ' (+' + pScore + ')');

  // A cold viewer converts on the entry product, not the high ticket.
  if (o.Tier === 'Low') { score += 5; why.push('entry-tier offer for a cold viewer (+5)'); }
  if (o.Tier === 'Premium' || o.Tier === 'Service') { score -= 10; why.push('high-ticket, needs warming first (-10)'); }

  return { score, why };
}

const paid = offers.filter(o => o.Tier === 'Low' || o.Tier === 'Premium' || o.Tier === 'Service');
const free = offers.filter(o => o.Tier === 'Free');

const ranked = paid.map(o => { const s = scoreOffer(o); return { offer: o, score: s.score, why: s.why }; })
                   .sort((a, b) => b.score - a.score);

const winner = ranked.length && ranked[0].score >= THRESHOLD ? ranked[0] : null;
const freeOffer = free[0] || null;

const stamp = new Date().toISOString();
const lines = [];
lines.push('OFFER ENGINE - ' + stamp);
lines.push(ctx.channel + ' | ' + (show || 'unassigned show') + ' | pillar: ' + (pillar || 'unset'));
lines.push('live offers considered: ' + offers.length + ' (' + paid.length + ' paid, ' + free.length + ' free)');
lines.push('threshold: ' + THRESHOLD);
lines.push('');

if (!offers.length) {
  lines.push('NO LIVE OFFERS for this brand. Every offer in the ladder is still Draft.');
  lines.push('The episode ships with no product CTA. That is correct - there is nothing to sell yet.');
} else {
  ranked.forEach((r, i) => {
    lines.push((i === 0 && winner ? '* ' : '  ') + r.offer.Name + ' - ' + r.score);
    r.why.forEach(w => lines.push('      ' + w));
  });
  lines.push('');
  if (winner) lines.push('ATTACHED: ' + winner.offer.Name + ' (' + winner.score + ' >= ' + THRESHOLD + ')');
  else lines.push('NO PAID OFFER ATTACHED - best score ' + (ranked.length ? ranked[0].score : 0) + ' is under threshold. Staying silent beats pitching something this episode did not earn.');
}
if (freeOffer) lines.push('FREE TIER: ' + freeOffer.Name + (freeOffer['Checkout URL'] ? ' -> ' + freeOffer['Checkout URL'] : ' (no URL set yet)'));

// Build the block packaging and the brief will actually write from.
const offerBlock = winner ? [
  'ATTACHED OFFER - weave this in naturally, never bolt it on.',
  'Name: ' + winner.offer.Name,
  'Price: $' + (winner.offer.Price != null ? winner.offer.Price : '?'),
  'Promise: ' + String(winner.offer.Promise || ''),
  'Problem it removes: ' + String(winner.offer['Problem Solved'] || ''),
  'Link: ' + String(winner.offer['Checkout URL'] || ''),
  '',
  'The offer earns its place by solving what this episode just proved is a problem.',
  'One mention, placed where the viewer feels the gap. Never open on it. Never repeat it.',
  'If a platform asset cannot carry it naturally, leave it out of that asset entirely.'
].join('\n') : [
  'NO PAID OFFER for this episode. Do not invent one and do not substitute another product.',
  freeOffer ? ('Free CTA only: ' + freeOffer.Name + ' - ' + String(freeOffer.Promise || '')) : 'No free CTA is live either - close on the content itself.'
].join('\n');

// Pass the manifest through untouched so packaging needs no rewiring, with the
// offer folded into the manifest JSON the packaging agent already reads.
let manifestJson = mfNode.manifestJson || '';
if (manifestJson) {
  try {
    const m = JSON.parse(manifestJson);
    m.attached_offer = winner ? {
      name: winner.offer.Name, price: winner.offer.Price,
      promise: winner.offer.Promise, problem_solved: winner.offer['Problem Solved'],
      link: winner.offer['Checkout URL'] || '', tier: winner.offer.Tier,
      placement_rule: 'One mention, where the viewer feels the gap. Never the opener. Omit from any asset that cannot carry it naturally.'
    } : { name: null, note: 'No offer matched this episode. Do not invent or substitute one.' };
    if (freeOffer) m.free_cta = { name: freeOffer.Name, link: freeOffer['Checkout URL'] || '', promise: freeOffer.Promise };
    manifestJson = JSON.stringify(m, null, 2);
  } catch (e) { manifestJson += '\n\n' + offerBlock; }
} 

return [{ json: {
  airtableId: mfNode.airtableId,
  manifest: mfNode.manifest,
  manifestJson,
  manifestError: mfNode.manifestError,
  offerName: winner ? winner.offer.Name : '',
  offerScore: winner ? winner.score : (ranked.length ? ranked[0].score : 0),
  offerLink: winner ? String(winner.offer['Checkout URL'] || '') : '',
  offerTier: winner ? winner.offer.Tier : '',
  offerId: winner ? winner.offer.id : '',
  freeCtaName: freeOffer ? freeOffer.Name : '',
  freeCtaLink: freeOffer ? String(freeOffer['Checkout URL'] || '') : '',
  offerBlock,
  offerReport: lines.join('\n')
} }];

