// Normalise into a rail-agnostic sale object. Everything downstream reads this
// shape, so adding Stripe later means writing one more normaliser and nothing else.
//
// GUARD, rebuilt 2026-09-08. Gumroad signs nothing, so the unguessable webhook
// path is the only barrier at the door. Every value below is therefore taken from
// Gumroad's own API and never from the ping. The ping is a rumour that a sale
// happened; the API is the record of whether it did. The credential IS the proof:
// /v2/sales/:id is scoped to the token's own account, so a sale that is not ours
// cannot come back 200. A forged ping can at most cause a harmless re-read.
//
// A success response is a claim, not a receipt: the HTTP node runs with
// neverError + fullResponse and its status code is read back here.
const r = $json || {};
const code = Number(r.statusCode);
const body = r.body || {};

const preflight = $('Gumroad: Preflight Ping').first().json || {};
const wantedId = String(preflight.saleId || '');
const ping = preflight.pingBody || {};

if (code !== 200) {
  const hint = (code === 401 || code === 403)
    ? 'The Gumroad credential on "Gumroad: Verify Sale" is missing, wrong, or lacks the view_sales scope.'
    : (code === 404)
      ? 'Gumroad has no such sale under this account. If this was the Gumroad test ping, that is expected: a test ping is not a real sale and cannot be verified.'
      : 'Gumroad did not answer 200.';
  throw new Error('REFUSED: sale ' + wantedId + ' was NOT recorded. Gumroad returned HTTP ' + (isFinite(code) ? code : '(no status)') + '. ' + hint + ' Nothing was written.');
}
if (body.success !== true) {
  throw new Error('REFUSED: Gumroad returned 200 but success was not true for sale ' + wantedId + '. Body keys: ' + (Object.keys(body).join(', ') || '(none)') + '. Nothing was written.');
}

const s = body.sale;
if (!s || typeof s !== 'object') {
  throw new Error('REFUSED: Gumroad returned 200 but carried no sale object for ' + wantedId + '. Body keys: ' + (Object.keys(body).join(', ') || '(none)') + '. Nothing was written.');
}

const gotId = String(s.id || '').trim();
if (gotId !== wantedId) {
  throw new Error('REFUSED: Gumroad returned a different sale than the one asked for. Asked ' + wantedId + ', got ' + (gotId || '(none)') + '. Nothing was written.');
}

// Price is read, never defaulted. A missing price silently becoming 0 would file a
// real sale as free revenue, which is worse than dropping the ping.
if (s.price === undefined || s.price === null || s.price === '') {
  throw new Error('REFUSED: Gumroad sale ' + wantedId + ' carried no price field, so the amount cannot be trusted. Sale keys: ' + (Object.keys(s).join(', ') || '(none)') + '. Nothing was written.');
}
const cents = Number(s.price);
if (!isFinite(cents)) {
  throw new Error('REFUSED: Gumroad sale ' + wantedId + ' price was not a number ("' + String(s.price) + '"). Nothing was written.');
}

const email = String(s.email || '').trim().toLowerCase();
if (!email) {
  throw new Error('REFUSED: Gumroad sale ' + wantedId + ' carried no email. Sale keys: ' + (Object.keys(s).join(', ') || '(none)') + '. Nothing was written.');
}

const truthy = v => v === true || String(v) === 'true';

const sale = {
  rail: 'Gumroad',
  orderId: gotId,
  email,
  name: String(s.full_name || s.purchaser_name || '').trim(),
  productName: String(s.product_name || '').trim(),
  permalink: String(s.permalink || s.product_permalink || '').trim(),
  amount: Math.round(cents) / 100,
  currency: String(s.currency || 'usd').toUpperCase(),
  quantity: Number(s.quantity) || 1,
  purchasedAt: String(s.created_at || s.sale_timestamp || new Date().toISOString()),
  isTest: truthy(s.test) || truthy(ping.test),
  refunded: truthy(s.refunded) || truthy(s.disputed)
};

return [{ json: sale }];

// Match the sale to a catalogue offer so revenue lands against a brand and,
// where possible, against the episode that produced it.
const sale = $('Gumroad: Normalise Sale').first().json;
const offers = ($json.records || []).map(r => ({ id: r.id, ...(r.fields || {}) }));

const norm = s => String(s || '').toLowerCase().replace(/[^a-z0-9]/g, '');
const saleName = norm(sale.productName);
const salePerma = norm(sale.permalink);

let match = offers.find(o => {
  const url = norm(o['Checkout URL']);
  return salePerma && url && url.includes(salePerma);
});
if (!match) match = offers.find(o => norm(o.Name) === saleName);
if (!match && saleName) match = offers.find(o => saleName.includes(norm(o.Name)) || norm(o.Name).includes(saleName));

const brand = match ? String(match.Brand || '') : '';

return [{ json: {
  ...sale,
  offerId: match ? match.id : '',
  offerName: match ? match.Name : sale.productName,
  offerTier: match ? match.Tier : '',
  brand: brand || 'The Quiet Operator',
  brandResolved: !!brand,
  mlGroupId: match ? String(match['MailerLite Group ID'] || '') : '',
  priorUnits: match ? (Number(match['Units Sold']) || 0) : 0,
  priorRevenue: match ? (Number(match.Revenue) || 0) : 0,
  matchNote: match
    ? ('Matched to offer "' + match.Name + '".')
    : ('NO CATALOGUE MATCH for Gumroad product "' + sale.productName + '" (permalink ' + sale.permalink + '). Revenue recorded, but not attributed to an offer. Add this product to the Offers table with its Checkout URL so the next sale attributes cleanly.')
} }];

// Returns nothing at all on a duplicate or a test ping, which stops the branch
// cleanly. One record per order - attribution needs the order, not the person.
const sale = $('Gumroad: Match Offer').first().json;
const existing = ($json.records || []);

if (existing.length) return [];              // already recorded, replayed ping
if (sale.isTest) return [];                  // Gumroad test purchase
if (sale.refunded) return [];                // refunds handled separately

const notes = [sale.matchNote];
if (!sale.brandResolved) notes.push('Brand defaulted to The Quiet Operator because the product did not match a catalogue offer. Verify before trusting any brand-level revenue figure.');

return [{ json: {
  mlGroupId: sale.mlGroupId,
  offerId: sale.offerId,
  offerName: sale.offerName,
  email: sale.email,
  name: sale.name,
  newUnits: (sale.priorUnits || 0) + (sale.quantity || 1),
  newRevenue: Math.round(((sale.priorRevenue || 0) + sale.amount) * 100) / 100,
  body: { typecast: true, records: [{ fields: {
    'Email': sale.email,
    'Name': sale.name,
    'Brand': sale.brand,
    'Offer': sale.offerName,
    'Rail': 'Gumroad',
    'Order ID': sale.orderId,
    'Amount': sale.amount,
    'Purchased At': sale.purchasedAt,
    'Lifecycle Stage': 'New Buyer',
    'Order Count': sale.quantity || 1,
    'Total Spend': sale.amount,
    'Notes': notes.join(' ')
  } }] }
} }];

// GLOBAL RENDER LOCK.
//
// TQO renders on the hour, NCO Forge at :30, and a render with Wait 60s polling
// loops can easily run past thirty minutes. Both point at the same worker
// (150.136.200.85), the same Pexels quota and the same json2video capacity, and
// each brand's coast-clear check only ever looked at its own Airtable table.
// Two 4K ffmpeg jobs on a 4-core box do not fail cleanly - they time out, and
// with the reaper now releasing stuck rows that becomes a retry loop.
//
// Yielding costs one cycle. Colliding costs a render and a reap.

const ctx = $('Show Context: Render').first().json;
const busy = ($json.records || []);

if (busy.length) {
  const r = busy[0];
  const who = ctx.show === 'NCO' ? 'The Quiet Operator' : 'NCO Forge';
  const topic = (r.fields || {}).Topic || r.id;
  console.log('Render lock held by ' + who + ' ("' + topic + '"). ' + ctx.channel +
              ' yields this cycle and retries next hour. The stale-claim reaper releases ' +
              'any claim older than ' + (ctx.staleClaimHours || 3) + 'h, so this cannot wedge.');
  return [];
}

return $input.all();

// Returns the same shape Parse Script JSON did, so Save Script to Airtable
// needs no rewiring. If the doctor cannot run, the original draft passes
// through untouched: an audit that fails should never cost you the draft.
const prior = $('Build Doctor Prompt').first().json;
const o = prior.original || {};
const stamp = new Date().toISOString();

function passthrough(reason) {
  return [{ json: {
    ...o,
    doctorScore: 0,
    doctorVerdict: 'UNCHECKED',
    lastFeedback: 'Script doctor did not run at ' + stamp + '. ' + reason +
      '\n\nThe draft was saved unedited. Nothing was lost, but nothing was checked either.',
    correctionAttempts: 0
  } }];
}

const out = $json || {};
if ((out.stop_reason === 'max_tokens' || out.choices?.[0]?.finish_reason === 'length')) return passthrough('Response truncated at max_tokens.');
let raw = out.choices?.[0]?.message ? String(out.choices[0].message.content ?? '') : (out.content || []).filter(c => c.type === 'text').map(c => c.text).join('');
if (!raw.trim()) return passthrough('No response. Check the Cerebras Cloud credential on Run Script Doctor (Cerebras).');
raw = String(raw).trim().replace(/^```(json)?/i, '').replace(/```$/, '').trim();

let v;
try { v = JSON.parse(raw); }
catch (e) {
  const s = raw.indexOf('{'), en = raw.lastIndexOf('}');
  if (s === -1 || en === -1) return passthrough('Response was not JSON.');
  try { v = JSON.parse(raw.slice(s, en + 1)); } catch (e2) { return passthrough('JSON unparseable.'); }
}

const repaired = v.verdict === 'REPAIRED';
const script = String(v.script || o.script || '');
const emDashes = (script.match(/[—–]/g) || []).length;

const feedback = [
  'SCRIPT DOCTOR ' + String(v.verdict || '?') + ' — ' + (v.score ?? '?') + '/100 at ' + stamp,
  '',
  'DIAGNOSIS: ' + String(v.diagnosis || ''),
  '',
  ...(Array.isArray(v.preserved) && v.preserved.length ? ['PRESERVED:', ...v.preserved.map(p => '  - ' + p), ''] : []),
  ...(Array.isArray(v.notes) && v.notes.length ? ['NOTES:', ...v.notes.map(n => '  - ' + n)] : []),
  emDashes ? '\nWARNING: ' + emDashes + ' em or en dash(es) survived the pass. That is an absolute rule in the voice profile.' : ''
].filter(Boolean).join('\n').replace(/—/g, '-');

return [{ json: {
  recordId: o.recordId,
  title: String(v.title || o.title || ''),
  script,
  description: String(v.description || o.description || ''),
  tags: o.tags || '',
  learningObjective: String(o.learningObjective || ''),
  checklist: Array.isArray(o.checklist) ? o.checklist : [],
  broll: Array.isArray(v.broll) ? v.broll.map(String).map(s => s.trim()).filter(Boolean).join(', ') : (o.broll || ''),
  doctorScore: Number(v.score) || 0,
  doctorVerdict: String(v.verdict || 'PASS'),
  lastFeedback: feedback,
  correctionAttempts: repaired ? 1 : 0
} }];

// ORIGINALITY SCAN - two checks, both deterministic.
//
// This is not an AI detector. Classifiers are unstable and YouTube does not run
// one. The two things that actually carry risk are measurable: writing with no
// rhythm, and episodes that are each other with the topic swapped. Both are
// counted here rather than judged.

const d = $('Parse Doctor Verdict').first().json;
const script = String(d.script || '');
const prior = ($json.records || []).map(r => ({
  title: String((r.fields || {})['Video Title'] || (r.fields || {}).Topic || r.id),
  text: String((r.fields || {}).Script || '')
})).filter(p => p.text.length > 200);

/* ---------- 1. rhythm and tells ---------- */

const sentences = (script.replace(/\s+/g, ' ').match(/[^.!?]+[.!?]+|[^.!?]+$/g) || []).map(s => s.trim()).filter(Boolean);
const lens = sentences.map(s => s.split(/\s+/).filter(Boolean).length).filter(n => n > 0);
const mean = lens.reduce((a, b) => a + b, 0) / (lens.length || 1);
const sd = Math.sqrt(lens.reduce((a, n) => a + (n - mean) ** 2, 0) / (lens.length || 1));
const cv = mean ? sd / mean : 0;   // coefficient of variation

const low = String(script).toLowerCase();
const count = (re) => (script.match(re) || []).length;
const hits = (list) => list.filter(w => low.includes(w));

const CONNECTIVES = ['moreover', 'furthermore', 'delve', 'in the realm of', 'tapestry', 'testament to', "it's worth noting", 'it is worth noting', 'navigating the landscape'];
const HYPE = ['game changer', 'game-changer', 'secret weapon', 'crush it', 'supercharge', 'this changes everything', '10x', 'masterclass', 'unlock the'];
const INTENSIFIERS = ['truly', 'deeply', 'incredibly', 'absolutely', 'profound', 'transformative'];
const BAIT = ['agree?', 'thoughts?', 'what would you add', 'let me know in the comments'];
const OPENERS = ["in today's world", 'in todays world', 'let me tell you', 'in this day and age', 'welcome back', 'we all know'];

const dashes = count(/[—–]/g);
const negParallel = count(/\bit'?s not\b[^.?!]{1,60}\bit'?s\b/gi) + count(/\bnot (?:just|only)\b[^.?!]{1,60}\bbut\b/gi);
const tells = {
  connectives: hits(CONNECTIVES), hype: hits(HYPE), intensifiers: hits(INTENSIFIERS),
  bait: hits(BAIT), openers: hits(OPENERS)
};

let rhythm = 100;
const findings = [];
if (lens.length >= 8) {
  if (cv < 0.35) { rhythm -= 30; findings.push('sentence length is near-uniform (variation ' + cv.toFixed(2) + ', human prose usually sits above 0.50). Perfect symmetry is the strongest real tell there is.'); }
  else if (cv < 0.45) { rhythm -= 12; findings.push('sentence rhythm is flat (variation ' + cv.toFixed(2) + '). Some thoughts need three sentences and some need one.'); }
}
if (mean > 26) { rhythm -= 10; findings.push('average sentence is ' + mean.toFixed(0) + ' words. This gets read aloud.'); }
if (dashes) { rhythm -= 25; findings.push(dashes + ' em or en dash(es). The voice profile forbids them absolutely.'); }
if (negParallel > 2) { rhythm -= 10; findings.push(negParallel + ' negative-parallelism constructions. It is a habit, not a style.'); }
for (const [k, v] of Object.entries(tells)) {
  if (v.length) { rhythm -= v.length * 6; findings.push(k + ': ' + v.join(', ')); }
}
rhythm = Math.max(0, Math.min(100, Math.round(rhythm)));

/* ---------- 2. self-similarity ---------- */

const norm = t => String(t).toLowerCase().replace(/[^a-z0-9\s]/g, ' ').split(/\s+/).filter(Boolean);
function shingles(t, n = 5) {
  const w = norm(t), s = new Set();
  for (let i = 0; i + n <= w.length; i++) s.add(w.slice(i, i + n).join(' '));
  return s;
}
function jaccard(a, b) {
  if (!a.size || !b.size) return 0;
  let inter = 0;
  for (const x of a) if (b.has(x)) inter++;
  return inter / (a.size + b.size - inter);
}

const mine = shingles(script);
const firstLine = norm(sentences[0] || '').slice(0, 12).join(' ');
const overlaps = prior.map(p => ({
  title: p.title,
  overlap: jaccard(mine, shingles(p.text)),
  sameOpener: firstLine && norm(p.text).slice(0, 12).join(' ').startsWith(firstLine.split(' ').slice(0, 5).join(' '))
})).sort((a, b) => b.overlap - a.overlap);

const worst = overlaps[0] || null;
let similarity = 100;
const simFindings = [];
if (worst) {
  // Independent prose on related topics lands near 0.02. Above 0.10 means shared
  // scaffolding; above 0.18 means the same episode wearing a different topic.
  if (worst.overlap >= 0.18) { similarity -= 55; simFindings.push('shares ' + (worst.overlap * 100).toFixed(1) + '% of its 5-word sequences with "' + worst.title + '". That is the same episode with the topic swapped, and it is exactly what the spam policy names.'); }
  else if (worst.overlap >= 0.10) { similarity -= 25; simFindings.push('shares ' + (worst.overlap * 100).toFixed(1) + '% of its 5-word sequences with "' + worst.title + '". Shared scaffolding. Vary the structure.'); }
  else if (worst.overlap >= 0.06) { similarity -= 8; simFindings.push('mild overlap (' + (worst.overlap * 100).toFixed(1) + '%) with "' + worst.title + '".'); }
  const openerClash = overlaps.filter(o => o.sameOpener);
  if (openerClash.length) { similarity -= 20; simFindings.push('opens the same way as ' + openerClash.length + ' earlier episode(s). The cold open is the one place a series cannot repeat itself.'); }
}
if (!prior.length) simFindings.push('no prior episodes in this show to compare against. First of its series.');
similarity = Math.max(0, Math.min(100, Math.round(similarity)));

const originality = Math.round(rhythm * 0.4 + similarity * 0.6);
const stamp = new Date().toISOString();

const report = [
  'ORIGINALITY SCAN ' + originality + '/100 at ' + stamp,
  '  rhythm & tells: ' + rhythm + '/100   self-similarity: ' + similarity + '/100',
  '  sentences ' + lens.length + ', mean ' + mean.toFixed(1) + ' words, variation ' + cv.toFixed(2) + ', compared against ' + prior.length + ' prior episode(s)',
  ...(findings.length ? ['', 'TELLS:', ...findings.map(f => '  - ' + f)] : ['', 'TELLS: none found.']),
  ...(simFindings.length ? ['', 'SIMILARITY:', ...simFindings.map(f => '  - ' + f)] : []),
  '',
  'This is not an AI-detector score. It counts rhythm, banned constructions and overlap with your own',
  'back catalogue, because those are the things that actually carry policy risk.'
].join('\n');

return [{ json: {
  ...d,
  originalityScore: originality,
  rhythmScore: rhythm,
  similarityScore: similarity,
  originalityReport: report,
  lastFeedback: String(d.lastFeedback || '') + '\n\n' + report
} }];

// PRE-FLIGHT.
//
// The lane used to run Manifest, Packaging, Packaging Grade and a thumbnail
// render before OS 30 asked whether Human Review was ticked. On a row that
// could never clear, that is three model calls and a render worker poll spent
// to reach a conclusion available from the row itself.
//
// This checks only the STATIC gates: the ones whose answer cannot change during
// the run. Anything the run itself produces (packaging, thumbnail, QC, grade)
// is deliberately not checked here, because those are why the run exists.
//
// This is not the gate. OS 30 is the gate. This refuses to pay for a verdict it
// can already predict.

const ctx = $('Show Context: Publish').first().json;
const f = $json;
const s = v => String(v ?? '').trim();
const blockers = [];

// Authorship, and it must agree with OS 30 exactly. See the long note in
// 'OS 28: Publish Gate': the data tables store human_review as a string, so
// `!== true` blocked every data table row here too. This list is a deliberate
// duplicate of the one there and the two must not drift.
const TICKED = ['true', 'yes', 'y', '1', 'checked', 'ticked'];
const reviewRaw = f['Human Review'];
const reviewStr = String(reviewRaw ?? '').trim().toLowerCase();
if (!(reviewRaw === true || TICKED.includes(reviewStr))) {
  blockers.push('Human Review is not ticked'
    + (reviewStr ? ' (found "' + String(reviewRaw).trim() + '")' : '')
    + '. Accepted: ' + TICKED.join(', '));
}

const disc = s(f['AI Disclosure']);
if (!['Not required', 'Disclosed in description', 'Disclosed on-screen + description'].includes(disc)) {
  blockers.push(disc ? 'AI Disclosure is "' + disc + '"' : 'AI Disclosure is unset');
}

const missing = [];
if (!s(f.Show)) missing.push('Show');
if (f.Season == null || f.Season === '') missing.push('Season');
if (f.Episode == null || f.Episode === '') missing.push('Episode');
if (!s(f['Asset Type'])) missing.push('Asset Type');
if (missing.length) blockers.push('content identity: no ' + missing.join(', '));

if (s(f['Published URL']) || s(f['Live Links'])) blockers.push('already carries a published or live URL');
if (s(f['System Status']).startsWith('publishing')) blockers.push('claimed by an unfinished publish attempt (' + s(f['System Status']) + ')');

const recheck = s(f['Recheck By']);
if (recheck && new Date(recheck + 'T23:59:59Z') < new Date()) blockers.push('Recheck By ' + recheck + ' is past');

const title = s(f['Video Title']);
const desc = s(f.Description);
if (!title) blockers.push('no Video Title');
else if (title.length > 95) blockers.push('title is ' + title.length + ' chars, house limit is 95');
if (!desc) blockers.push('no Description');
else if (desc.length < 120) blockers.push('description is only ' + desc.length + ' chars, floor is 120');

if (!s(f.Script)) blockers.push('no Script');

const ok = blockers.length === 0;
const stamp = new Date().toISOString();
const report = ok
  ? 'PRE-FLIGHT CLEARED at ' + stamp + '. Static gates pass; spending the run.'
  : ['PRE-FLIGHT SKIPPED at ' + stamp,
     ctx.channel + ' | ' + (s(f.Show) || 'unassigned') + ' | ' + title,
     '',
     'This row cannot clear OS 30 as it stands, so the run was not paid for:',
     ...blockers.map(b => '  - ' + b),
     '',
     'Nothing was generated and nothing was changed. Fix the above and it enters',
     'the next publish cycle on its own.'].join('\n');

return [{ json: { ...f, _preflightOk: ok, _preflightReport: report, _preflightBlockers: blockers } }];

// Output ceiling for the packaging call, kept here rather than buried in the
// prompt builder so it can be raised without touching prompt logic.
//
// Since the atomizer landed this one call returns the primitive map, 2-3
// mid-form segments, 5 shorts, 3 LinkedIn posts, 5 X threads, a carousel,
// 10 title candidates, 5 thumbnail angles, a community prompt and every
// caption. Truncation does not throw here; Parse Packaging raises max_tokens
// in its error, but the run is already lost by then. Budget generously; you
// are billed on what is produced, not on the ceiling.
const MAX_TOKENS = 24000;

const j = { ...$json };
if (j.claudeBody) j.claudeBody = { ...j.claudeBody, max_tokens: MAX_TOKENS };
// Cerebras gpt-oss-120b carries this call from 15 Sep 2026, on Tee's ruling that
// every model call in this workflow moves off Anthropic. The prompt builder still
// emits the Anthropic shape, so the whole swap is this conversion here and one
// extraction line in the parser downstream. max_completion_tokens on Cerebras
// INCLUDES the model's reasoning tokens, which is why the ceiling above stays
// generous rather than trimmed to the prose.
const SUFFIX = '\n\nOutput rules that override anything above: never use an em dash or an en dash anywhere in any field, use a comma, a full stop or the word to instead; write the full length the brief asks for, never shorter.';
