// Output ceiling for the merged QC pass.
//
// Since QC and the packaging grade became one call, this single response has to
// carry 8 episode dimensions with findings AND a per-asset grade across all 10
// repurpose assets with a fix for each. 5000 was the sum of the two old calls
// minus the duplication, which was optimistic.
//
// Truncation fails closed to HOLD, which is safe but silent: you would see a
// held row and no obvious reason. Raising the ceiling is cheaper than debugging
// that on a Monday.
const MAX_TOKENS = 9000;

const j = { ...$json };
if (j.claudeBody) j.claudeBody = { ...j.claudeBody, max_tokens: MAX_TOKENS };
// Cerebras gpt-oss-120b carries this call from 15 Sep 2026, on Tee's ruling that
// every model call in this workflow moves off Anthropic. The prompt builder still
// emits the Anthropic shape, so the whole swap is this conversion here and one
// extraction line in the parser downstream. max_completion_tokens on Cerebras
// INCLUDES the model's reasoning tokens, which is why the ceiling above stays
// generous rather than trimmed to the prose.
const SUFFIX = '\n\nOutput rules that override anything above: never use an em dash or an en dash anywhere in any field, use a comma, a full stop or the word to instead; write the full length the brief asks for, never shorter.';
const toCerebras = (b) => {
  if (!b || !Array.isArray(b.messages)) return b;
  const sys = (typeof b.system === 'string' && b.system) ? [{ role: 'system', content: b.system + SUFFIX }] : [];
  return { model: 'gpt-oss-120b', messages: [...sys, ...b.messages], max_completion_tokens: MAX_TOKENS, reasoning_effort: 'medium', response_format: { type: 'json_object' } };
};
if (j.body) j.body = toCerebras(j.body);
if (j.claudeBody) j.claudeBody = toCerebras(j.claudeBody);
return [{ json: j }];

// Output ceiling for the script draft.
// The prompt asks for 1200 to 2000 words with a hard floor of 1200. That is
// roughly 2700 tokens of prose, but it arrives JSON-escaped alongside a title,
// a description and an 8 to 12 item broll array. Headroom is free; you are
// billed on what is produced, not on the ceiling.
const MAX_TOKENS = 10000;

const j = { ...$json };
if (j.body) j.body = { ...j.body, max_tokens: MAX_TOKENS };
if (j.claudeBody) j.claudeBody = { ...j.claudeBody, max_tokens: MAX_TOKENS };
// Cerebras gpt-oss-120b carries this call from 15 Sep 2026, on Tee's ruling that
// every model call in this workflow moves off Anthropic. The prompt builder still
// emits the Anthropic shape, so the whole swap is this conversion here and one
// extraction line in the parser downstream. max_completion_tokens on Cerebras
// INCLUDES the model's reasoning tokens, which is why the ceiling above stays
// generous rather than trimmed to the prose.
const SUFFIX = '\n\nOutput rules that override anything above: never use an em dash or an en dash anywhere in any field, use a comma, a full stop or the word to instead; write the full length the brief asks for, never shorter.';
const toCerebras = (b) => {
  if (!b || !Array.isArray(b.messages)) return b;
  const sys = (typeof b.system === 'string' && b.system) ? [{ role: 'system', content: b.system + SUFFIX }] : [];
  return { model: 'gpt-oss-120b', messages: [...sys, ...b.messages], max_completion_tokens: MAX_TOKENS, reasoning_effort: 'medium', response_format: { type: 'json_object' } };
};
if (j.body) j.body = toCerebras(j.body);
if (j.claudeBody) j.claudeBody = toCerebras(j.claudeBody);
// The writer undershoots. Measured 15 Sep 2026 on the real TQO prompt: asked
// for 1200 to 2000 it returned 894 and 798; asked for 1500 to 1900 in the user
// turn it returned 1055 and 1059. The ask below sits above the target on
// purpose so the delivered length lands inside the brief, and the Script Gate
// holds anything that still comes in under 1200.
const LENGTH_LINE = '\n\nLength requirement: the script field must run at least 1800 words and at most 2200. Under 1200 words is a failed output. Write every one of the 8 to 12 sections in full, each with its own example or number, and do not summarise sections you have not yet written.';
if (j.body && Array.isArray(j.body.messages)) {
  const last = j.body.messages[j.body.messages.length - 1];
  if (last && last.role === 'user' && typeof last.content === 'string') last.content = last.content + LENGTH_LINE;
}
