// Thumbnail planning, TQO-native.
//
// Was: Adapt: Render Thumbnail -> TSWS 00 -> a render worker whose URL is still
// the literal string RENDER-WORKER-URL-HERE. That bridge has never connected,
// so no thumbnail has ever rendered. This path uses the json2video renderer
// that already produces the videos, and touches nothing belonging to TSWS.
const ctx = $('Show Context: Publish').first().json;
const pk  = $('Parse Packaging').first().json;
const row = $('One Row at a Time').first().json;
const f   = row.fields || row;
const mf  = $('Offer Engine: Select').first().json;

const isNCO = ctx.show === 'NCO';

// Headline. A row that was packaged before it was written carries the
// headline the audience was promised in thumbnail_headline, and package_locked
// holds Tee's pick (1, 2 or 3, or his own mark), set by hand, never by the
// model. That headline wins. The atomizer's first concept is only the fallback
// for a row that was never packaged, which is the pre 22 Sep 2026 path. Reading
// the raw package_locked key because the DT shim's alias map does not carry it.
const packageLocked = !!String(row.package_locked || '').trim();
const lockedHead = packageLocked ? String(f['Thumbnail Headline'] || row.thumbnail_headline || '').trim() : '';
let head = String(lockedHead || pk.thumbText || f['Thumbnail Headline'] || f['Video Title'] || f.Topic || '').trim();
head = head.replace(/[—–]/g, ' ').replace(/\s+/g, ' ');
// Word ceiling from the brand spec: TQO 5, NCO Forge 4.
const cap = isNCO ? 4 : 5;
const words = head.split(' ').filter(Boolean);
if (words.length > cap) head = words.slice(0, cap).join(' ');
head = head.toUpperCase();

// Backdrop query: a concrete subject, never an abstract concept. Abstractions
// are not searchable and return the generic AI-channel look.
let q = String(f['Primary Subject'] || '').trim();
if (!q) {
  const m = mf.manifest || {};
  const vis = Array.isArray(m.visual_metaphors) ? m.visual_metaphors : [];
  q = String(vis[0] || '').trim();
}
if (!q) q = isNCO ? 'soldier briefing room low light' : 'professional desk window evening';

// Pexels matches nouns, not sentences. A full clause returns the generic
// stock look because no single clip is about a whole sentence. Strip the
// connective words and keep the first few content words.
const STOP = new Set(['a','an','the','of','to','in','on','at','by','for','with',
  'and','or','but','is','are','was','were','be','being','been','that','this',
  'these','those','your','you','their','its','it','as','from','into','over',
  'every','all','each','one','showing','being','switched','broadcasting']);
const qWords = q.toLowerCase().replace(/[^a-z0-9\s]/g, ' ').split(/\s+/)
  .filter(w => w && !STOP.has(w));
const query = (qWords.slice(0, 4).join(' ') || q).trim();

return [{ json: {
  airtableId: pk.airtableId,
  brand: ctx.brand,
  kicker: ctx.kicker,
  headline: head,
  headlineSource: lockedHead ? 'locked package' : (pk.thumbText ? 'atomizer concept 1' : 'row field or title'),
  query,
  queryRaw: q,
  isNCO,
} }];

// Choose the backdrop and compute the layout the compositor will draw.
//
// MERGED 2026-09-30 from the Tee-supplied n8n thumbnail packages: per-show
// brand palettes now come from the locked brand profiles in each package,
// replacing the old two-show ink/accent guess. Palettes: TQO navy #0A1628 +
// amber gold #D4A017; NCO Forge Field Charcoal #171C18 + Combat Khaki #A69F80;
// ACX Void #04090F + Signal Cyan #36D1D8 (Critic Red never on thumbnails,
// verdicts only); TSWS Void #050308 + His Sapphire #5D9DFF.
const p = $('Thumb: Plan').first().json;
const photos = ($json.photos || []);
const pick = photos.find(x => x && x.src && (x.src.landscape || x.src.large2x)) || photos[0] || null;
const src = pick ? (pick.src.landscape || pick.src.large2x || pick.src.large) : null;

// Brand palettes, one entry per show, from the locked package profiles.
const SHOW = String(p.show || (p.isNCO ? 'NCO' : 'TQO')).toUpperCase();
const BRAND = {
  TQO:  { ink: '#0A1628', accent: '#D4A017' },
  NCO:  { ink: '#171C18', accent: '#A69F80' },
  ACX:  { ink: '#04090F', accent: '#36D1D8' },
  TSWS: { ink: '#050308', accent: '#5D9DFF' },
}[SHOW] || { ink: '#06080F', accent: '#C8A44D' };

const ink    = BRAND.ink;
const accent = BRAND.accent;

// Type scale. The headline sets in one of three sizes so a long headline stays
// inside the scrim instead of running over the photograph.
const head = String(p.headline || '').trim();
const n = head.length;
const size = n <= 14 ? 104 : (n <= 24 ? 84 : 66);
const wrapAt = Math.max(8, Math.floor(700 / (size * 0.52)));

return [{ json: {
  airtableId: p.airtableId,
  headline: head,
  kicker: String(p.kicker || ''),
  photoUsed: src,
  photographer: pick ? (pick.photographer || '') : '',
  ink, accent,
  scrimColor: ink + 'D9',
  headSize: size,
  headWrap: wrapAt,
  headY: n <= 14 ? 250 : (n <= 24 ? 235 : 225)
} }];

// The family key. Everything derived from this episode carries it: primitives,
// assets, publishing slots, measurements, audience signals.
//
// Deliberately derived rather than sequential. A sequential NF-0047 needs a
// counter, a counter needs a read before every write, and a read-then-write
// under concurrency eventually issues the same number twice. Show, season and
// episode already uniquely identify an episode, so the key is computed and
// cannot collide.
const ctx = $('Show Context: Publish').first().json;
const row = $('One Row at a Time').first().json;
const f   = row.fields || row;
const pk  = $('Parse Packaging').first().json;

const isNCO = ctx.show === 'NCO';
const prefix = isNCO ? 'NF' : 'TQO';
const slug = (String(f.Show || '').replace(/[^A-Za-z]/g, '').toUpperCase().slice(0, 3)) || 'GEN';
const season = (f.Season != null ? f.Season : 0);
const ep = (f.Episode != null ? f.Episode : 0);

const existing = String(f['Content ID'] || '').trim();
const contentId = existing || (prefix + '-' + slug + '-S' + season + 'E' + String(ep).padStart(2, '0'));

return [{ json: {
  contentId,
  brand: ctx.channel,
  isNCO,
  tableId: ctx.tableId,
  tableRef: ctx.tableRef,
  episodeRow: String(f.id || pk.airtableId || ''),
  show: String(f.Show || ''),
  season, episode: ep,
  title: String(f['Video Title'] || f.Topic || ''),
  mintedNow: !existing
} }];

// Every extracted primitive becomes a row, including the ones nothing was built
// from. A high-strength primitive with zero assets is the more interesting
// record: it is an idea the episode surfaced and the packaging failed to use.
const fam = $json;
const pk = $('Parse Packaging').first().json;
const prims = Array.isArray(pk.primitives) ? pk.primitives : [];
if (!prims.length) return [];

// Count how many surviving assets cited each primitive.
const used = {};
function tally(arr) { (arr || []).forEach(a => { const k = String(a && a.from || ''); if (k) used[k] = (used[k] || 0) + 1; }); }
tally(pk.shortScripts); tally(pk.midformSegments); tally(pk.titles); tally(pk.thumbnailConcepts);
if (pk.carousel) tally([pk.carousel]);

const now = new Date().toISOString();
const records = prims.map(p => ({
  fields: {
    'Primitive ID': fam.contentId + '-' + String(p.id || 'P?'),
    'Content ID': fam.contentId,
    'Brand': fam.brand,
    'Type': String(p.type || '').toUpperCase(),
    'Strength': Number(p.strength || 0),
    'Source Text': String(p.source_text || ''),
    'Note': String(p.note || ''),
    'Episode Row': fam.episodeRow,
    'Show': fam.show,
    'Season': fam.season,
    'Episode': fam.episode,
    'Assets Built': used[String(p.id || '')] || 0,
    'Extracted At': now
  }
}));

const out = [];
for (let i = 0; i < records.length; i += 10) {
  out.push({ json: { body: { typecast: true, records: records.slice(i, i + 10) } } });
}
return out;

// One row per asset. The From Primitive field is the whole point: an asset that
// cannot name its source idea should not exist, and Parse Packaging has already
// dropped those. What lands here is what survived.
const fam = $('Family: Assign IDs').first().json;
const pk  = $('Parse Packaging').first().json;
const prims = Array.isArray(pk.primitives) ? pk.primitives : [];
const strength = {};
prims.forEach(p => { if (p && p.id) strength[String(p.id)] = Number(p.strength || 0); });

const now = new Date().toISOString();
const rows = [];
let n = 0;
function add(kind, code, o) {
  n += 1;
  rows.push({ fields: Object.assign({
    'Asset ID': fam.contentId + '-' + code + '-' + String(n).padStart(2, '0'),
    'Content ID': fam.contentId,
    'Brand': fam.brand,
    'Kind': kind,
    'From Primitive': o.from ? (fam.contentId + '-' + o.from) : '',
    'Primitive Strength': strength[String(o.from || '')] || null,
    'Status': 'Draft',
    'Episode Row': fam.episodeRow,
    'Show': fam.show,
    'Season': fam.season,
    'Episode': fam.episode,
    'Created At': now
  }, o.fields || {}) });
}

(pk.midformSegments || []).forEach(m => add('Mid-form', 'MF', { from: m.from, fields: {
  'Angle': String(m.title || ''), 'Function': 'FRAMEWORK',
  'Body': 'COLD OPEN: ' + String(m.cold_open || '') + '\n\nOUTLINE: ' + String(m.outline || ''),
  'Est Seconds': Math.round(Number(m.est_minutes || 0) * 60) || null } }));

(pk.shortScripts || []).forEach(s => add('Short', 'SH', { from: s.from, fields: {
  'Function': String(s.function || '').toUpperCase() || null,
  'Angle': String(s.angle || ''), 'Hook Type': String(s.hook_type || ''),
  'Body': 'HOOK spoken: ' + String(s.hook_spoken || '') + '\nHOOK on-screen: ' + String(s.hook_onscreen || '') +
          '\n\nBODY: ' + String(s.body || '') + '\n\nCTA: ' + String(s.cta || ''),
  'Est Seconds': Number(s.est_seconds || 0) || null } }));

(pk.titles || []).forEach(t => add('Title', 'TI', { from: t.from, fields: {
  'Angle': String(t.family || ''), 'Body': String(t.title || '') } }));

(pk.thumbnailConcepts || []).forEach(t => add('Thumbnail', 'TH', { from: t.from, fields: {
  'Angle': String(t.angle || ''), 'Body': String(t.text || ''),
  'Notes': 'visual: ' + String(t.visual || '') } }));

if (pk.carousel) add('Carousel', 'CR', { from: pk.carousel.from, fields: {
  'Function': 'FRAMEWORK', 'Angle': String(pk.carousel.title || ''),
  'Body': (pk.carousel.slides || []).map((s, i) => (i + 1) + '. ' + s).join('\n') } });

if (pk.community && pk.community.poll_question) add('Poll', 'PO', { from: '', fields: {
  'Function': 'QUESTION', 'Body': String(pk.community.poll_question) + '\n' +
    (pk.community.poll_options || []).map((o, i) => String.fromCharCode(65 + i) + '. ' + o).join('\n') } });
if (pk.community && pk.community.open_question) add('Question', 'QU', { from: '', fields: {
  'Function': 'QUESTION', 'Body': String(pk.community.open_question) } });

if (!rows.length) return [];
const out = [];
for (let i = 0; i < rows.length; i += 10) {
  out.push({ json: { count: rows.length, body: { typecast: true, records: rows.slice(i, i + 10) } } });
}
return out;

// Numbers are assigned once and never reused, even when a rule is later
// retired. Reusing a number would break every graphic, short and newsletter
// section that already carries the old one.
const fam = $('Family: Assign IDs').first().json;
const pk  = $('Parse Packaging').first().json;
const rule = String(pk.canonicalRule || '').trim();
if (!rule) return [];

const recs = ($json.records || []);
const maxNum = recs.reduce((m, r) => Math.max(m, Number((r.fields || {})['Number'] || 0)), 0);

// Dedupe on normalised text. Two episodes landing on the same principle is not
// a failure, but it should be visible rather than quietly doubling the library.
function norm(s) { return String(s || '').toLowerCase().replace(/[^a-z0-9 ]/g, '').replace(/\s+/g, ' ').trim(); }
const target = norm(rule);
const dupe = recs.find(r => norm((r.fields || {})['Rule']) === target);

const prefix = fam.isNCO ? 'FR' : 'QM';
const number = maxNum + 1;
const ruleId = prefix + '-' + String(number).padStart(3, '0');

if (dupe) {
  const existingId = (dupe.fields || {})['Rule ID'] || '';
  return [{ json: {
    skipWrite: true,
    ruleId: existingId,
    note: 'This episode landed on a principle already in the library as ' + existingId + '. No new number issued.',
    body: null
  } }];
}

return [{ json: {
  skipWrite: false,
  ruleId,
  body: { typecast: true, records: [{ fields: {
    'Rule ID': ruleId,
    'Number': number,
    'Brand': fam.brand,
    'Rule': rule,
    'Status': 'Draft',
    'Content ID': fam.contentId,
    'Episode Row': fam.episodeRow,
    'Show': fam.show,
    'From Primitive': fam.contentId + '-' + String((pk.carousel && pk.carousel.from) || ''),
    'Times Reused': 0,
    'Created At': new Date().toISOString()
  } }] }
} }];

// The stagger is the point. Publishing everything on launch day gives one
// episode one day of life; spreading it gives the same episode three weeks,
// and gives the analytics layer something to compare a slow burn against.
const fam = $('Family: Assign IDs').first().json;

// Recover the asset ids from the rows we just wrote, rather than recomputing
// them with a second copy of the numbering logic.
const assets = [];
try {
  $('Assets: Build Rows').all().forEach(it => {
    ((it.json.body || {}).records || []).forEach(r => {
      const f = r.fields || {};
      assets.push({ id: f['Asset ID'], kind: f['Kind'], fn: f['Function'] || '', body: f['Body'] || '' });
    });
  });
} catch (e) { /* no assets written */ }
if (!assets.length) return [];

const shorts = assets.filter(a => a.kind === 'Short');
const byFn = fn => shorts.find(s => s.fn === fn) || null;
const first = kind => assets.find(a => a.kind === kind) || null;

// Day 0 is now. This node runs at publish time, so now is launch.
const base = new Date();
function at(dayOffset, hourET) {
  const d = new Date(base.getTime() + dayOffset * 86400000);
  d.setUTCHours(hourET + 4, 0, 0, 0); // ET is UTC-4 in August
  return d.toISOString();
}

const plan = [
  { day: 0,  hour: 9,  asset: first('Long Form'), platforms: ['YouTube'] },
  { day: 1,  hour: 12, asset: byFn('CONFLICT'),   platforms: ['YouTube Shorts', 'TikTok', 'Instagram'] },
  { day: 2,  hour: 8,  asset: first('LinkedIn'),  platforms: ['LinkedIn', 'Facebook'] },
  { day: 3,  hour: 12, asset: byFn('RULE'),       platforms: ['Instagram', 'X'] },
  { day: 4,  hour: 8,  asset: first('Carousel'),  platforms: ['LinkedIn', 'Instagram'] },
  { day: 5,  hour: 12, asset: byFn('CONTRARIAN'), platforms: ['YouTube Shorts', 'TikTok'] },
  { day: 6,  hour: 7,  asset: first('Newsletter'),platforms: ['Newsletter'] },
  { day: 7,  hour: 10, asset: first('Poll'),      platforms: ['Community'] },
  { day: 7,  hour: 15, asset: first('Question'),  platforms: ['X'] },
  { day: 10, hour: 12, asset: byFn('STORY'),      platforms: ['YouTube Shorts', 'TikTok', 'Instagram'] },
  { day: 14, hour: 12, asset: first('Mid-form'),  platforms: ['YouTube'] },
  { day: 21, hour: 12, asset: byFn('QUESTION'),   platforms: ['YouTube Shorts', 'TikTok'] }
];

const rows = [];
const skipped = [];
plan.forEach(p => {
  if (!p.asset) { skipped.push('day ' + p.day + ': no asset of that kind was produced'); return; }
  p.platforms.forEach(pl => {
    rows.push({ fields: {
      'Slot ID': p.asset.id + '-' + pl.replace(/\s+/g, '').toUpperCase(),
      'Asset ID': p.asset.id,
      'Content ID': fam.contentId,
      'Brand': fam.brand,
      'Platform': pl,
      'Day Offset': p.day,
      'Scheduled For': at(p.day, p.hour),
      'Status': 'Pending',
      'Notes': skipped.length ? '' : ''
    } });
  });
});

if (!rows.length) return [];
const out = [];
for (let i = 0; i < rows.length; i += 10) {
  out.push({ json: { slots: rows.length, skipped, body: { typecast: true, records: rows.slice(i, i + 10) } } });
}
return out;

// EditForge already has a queue table with a defined contract: one row per
// frame or clip, Kind, Status, Prompt, Dest Path, Size. Writing into it is the
// integration. Inventing a second interface would mean two things to keep in
// sync and a URL somebody has to remember to fill in.
const fam = $('Family: Assign IDs').first().json;

const shorts = [];
try {
  $('Assets: Build Rows').all().forEach(it => {
    ((it.json.body || {}).records || []).forEach(r => {
      const f = r.fields || {};
      if (f['Kind'] === 'Short') shorts.push(f);
    });
  });
} catch (e) { /* nothing to queue */ }
if (!shorts.length) return [];

const brandDir = fam.isNCO ? 'nco-forge' : 'quiet-operator';
const records = shorts.map(s => ({ fields: {
  'Frame ID': s['Asset ID'],
  'Package': 'Ad hoc',
  'Kind': 'video',
  'Status': 'Queued',
  'Rider': 'none',
  'Size': '1080x1920',
  'Dest Path': '/' + brandDir + '/' + fam.contentId + '/' + s['Asset ID'] + '.mp4',
  'Prompt': [
    'VERTICAL SHORT, 1080x1920, for ' + fam.brand + '.',
    'Episode: ' + fam.title,
    'Content function: ' + (s['Function'] || 'unclassified'),
    'Angle: ' + (s['Angle'] || ''),
    '',
    s['Body'] || '',
    '',
    'Captions: two lines maximum, three to six words per line. Emphasis colour only on the',
    'decision point or the rule, never on every word. No bouncing word-by-word captions.'
  ].join('\n'),
  'QC Notes': 'Queued by TQO V5 publish lane. Content family ' + fam.contentId +
              '. Primitive ' + (s['From Primitive'] || 'none') + '.'
} }));

const out = [];
for (let i = 0; i < records.length; i += 10) {
  out.push({ json: { queued: records.length, body: { typecast: true, records: records.slice(i, i + 10) } } });
}
return out;

// Collect every published row from both brands and pull the YouTube id out of
// whatever URL shape it was stored in. Rows without a recognisable id are not
// an error; they are rows published somewhere that is not YouTube.
function ytId(u) {
  const s = String(u || '');
  let m = s.match(/[?&]v=([A-Za-z0-9_-]{11})/); if (m) return m[1];
  m = s.match(/youtu\.be\/([A-Za-z0-9_-]{11})/); if (m) return m[1];
  m = s.match(/\/shorts\/([A-Za-z0-9_-]{11})/); if (m) return m[1];
  m = s.match(/\/embed\/([A-Za-z0-9_-]{11})/); if (m) return m[1];
  return null;
}

const rows = [];
function collect(nodeName, brand) {
  let recs = [];
  try { recs = ($(nodeName).first().json.records || []); } catch (e) { return; }
  recs.forEach(r => {
    const f = r.fields || {};
    const id = ytId(f['Published URL']) || ytId(f['Live Links']) || ytId(f['Video URL']);
    if (!id) return;
    rows.push({
      videoId: id, brand,
      episodeRow: r.id,
      contentId: String(f['Content ID'] || ''),
      assetId: String(f['Content ID'] || '') ? (String(f['Content ID']) + '-LF-01') : '',
      show: String(f.Show || ''),
      assetType: String(f['Asset Type'] || 'Flagship'),
      publishDate: f['Publish Date'] || null
    });
  });
}
collect('Analytics: Fetch TQO Published', 'The Quiet Operator');
collect('Analytics: Fetch NCO Published', 'NCO Forge');

if (!rows.length) return [];

const out = [];
for (let i = 0; i < rows.length; i += 50) {
  const chunk = rows.slice(i, i + 50);
  out.push({ json: { ids: chunk.map(c => c.videoId).join(','), meta: chunk, total: rows.length } });
}
return out;

// A winner is defined against the channel, not against an absolute number.
// Five thousand views is an outlier on one channel and a disappointment on
// another, so the denominator is this brand's own median for this asset type.
const meta = ($json.meta || []);
const items = ($json.items || []);
if (!items.length) return [];

const byId = {};
meta.forEach(m => { byId[m.videoId] = m; });

const now = new Date();
const measured = now.toISOString();
const stamp = measured.slice(0, 10);

const parsed = items.map(v => {
  const m = byId[v.id] || {};
  const st = v.statistics || {};
  const sn = v.snippet || {};
  const pub = sn.publishedAt ? new Date(sn.publishedAt) : null;
  const days = pub ? Math.max(0, Math.round((now - pub) / 86400000)) : null;
  return {
    videoId: v.id, meta: m,
    views: Number(st.viewCount || 0),
    likes: Number(st.likeCount || 0),
    comments: Number(st.commentCount || 0),
    days
  };
});

// Trailing median views per brand, over everything in this pull.
function median(a) {
  const s = a.filter(x => x > 0).sort((x, y) => x - y);
  if (!s.length) return 0;
  const mid = Math.floor(s.length / 2);
  return s.length % 2 ? s[mid] : (s[mid - 1] + s[mid]) / 2;
}
const medians = {};
['The Quiet Operator', 'NCO Forge'].forEach(b => {
  medians[b] = median(parsed.filter(p => (p.meta.brand === b)).map(p => p.views));
});

const records = parsed.map(p => {
  const med = medians[p.meta.brand] || 0;
  const outlier = med > 0 ? Number((p.views / med).toFixed(2)) : null;
  const f = {
    'Measurement ID': (p.meta.contentId || p.videoId) + '-YT-' + stamp,
    'Content ID': p.meta.contentId || '',
    'Asset ID': p.meta.assetId || '',
    'Brand': p.meta.brand,
    'Platform': 'YouTube',
    'Platform ID': p.videoId,
    'Measured At': measured,
    'Days Since Post': p.days,
    'Views': p.views,
    'Likes': p.likes,
    'Comments': p.comments,
    'Outlier Score': outlier,
    'Notes': med > 0
      ? ('brand median in this pull: ' + med + ' views across ' + parsed.filter(x => x.meta.brand === p.meta.brand).length + ' videos')
      : 'no median available yet; not enough published videos on this brand to compare against'
  };
  if (outlier != null && outlier >= 1.5) f['Winner'] = 'Topic';
  return { fields: f };
});

const out = [];
for (let i = 0; i < records.length; i += 10) {
  out.push({ json: { measured: records.length, medians, body: { typecast: true, records: records.slice(i, i + 10) } } });
}
return out;

// Reuses the published-row fetch the analytics branch already paid for.
// Fifteen videos is a deliberate ceiling: the comment API is quota-metered and
// the signal on older videos has usually already been harvested.
const all = [];
$input.all().forEach(it => (it.json.meta || []).forEach(m => all.push(m)));
if (!all.length) return [];
return all.slice(0, 15).map(m => ({ json: m }));

// Classification is rule-based on purpose. A model would read intent slightly
// better, but it would also add a credential this branch does not otherwise
// need, and a branch that fails quietly because of an unbound key is worse
// than one that classifies a little more bluntly. The routing below is a
// candidate generator, not a publisher: Tee approves every idea it produces.
const WINDOW_DAYS = 7;
const cutoff = Date.now() - WINDOW_DAYS * 86400000;

// Comments already on file, so a daily run does not re-file the same thread.
const seen = new Set();
try {
  ($('Signals: Fetch Recent').first().json.records || []).forEach(r => {
    const id = (r.fields || {})['Signal ID']; if (id) seen.add(String(id));
  });
} catch (e) { /* first run */ }

const QUESTION = /^(how|what|why|when|where|which|who|can|could|should|do|does|did|is|are|any\s+advice)\b/i;
const STORY    = /\b(i (had|was|remember|once|used to)|when i was|my (soldier|nco|platoon|squad|boss|manager|team))\b/i;
const DEBATE   = /\b(disagree|not true|wrong|actually,|hard disagree|thats not|that is not|in my experience it)\b/i;
const COUNTER  = /\b(but |however |on the other hand|counterpoint|depends on)\b/i;
const PAIN     = /\b(i struggle|struggling|my problem|stuck|cant seem|burned out|burnt out|no idea how)\b/i;
const TOOL     = /\b(template|checklist|worksheet|do you have|where can i (get|find)|is there a (guide|pdf)|link to)\b/i;
const MISCON   = /\b(i thought|isnt it just|arent you supposed to|dont you have to)\b/i;
const PRAISE   = /^(great|good|love|excellent|thank|appreciate|solid|facts|real|this)\b.{0,60}$/i;

function classify(t) {
  const s = String(t || '').trim();
  if (s.length < 12) return 'Noise';
  if (TOOL.test(s)) return 'Tool request';
  if (STORY.test(s) && s.length > 120) return 'Story';
  if (DEBATE.test(s)) return 'Debate';
  if (PAIN.test(s)) return 'Recurring pain';
  if (MISCON.test(s)) return 'Misconception';
  if (QUESTION.test(s) || s.includes('?')) return 'Question';
  if (COUNTER.test(s) && s.length > 100) return 'Counterpoint';
  if (PRAISE.test(s)) return 'Praise';
  return 'Noise';
}

function route(cls, isNCO) {
  switch (cls) {
    case 'Question':       return isNCO ? 'NCO School' : 'The Quiet Advantage';
    case 'Story':          return isNCO ? 'NCO Confessions' : 'Flagship candidate';
    case 'Debate':         return isNCO ? 'Hard Call' : 'The AI Shift';
    case 'Counterpoint':   return 'Response Short';
    case 'Recurring pain': return 'Flagship candidate';
    case 'Tool request':   return 'Product opportunity';
    case 'Misconception':  return 'Response Short';
    default:               return 'None';
  }
}

// Normalised theme so recurrence is countable. Crude but stable: the four
// longest non-stop words, alphabetised.
const STOP = new Set(['about','after','again','because','been','before','being','between','could','doing','during','every','from','have','into','just','like','more','most','only','other','over','same','should','some','such','than','that','their','them','then','there','these','they','this','those','through','under','very','were','what','when','where','which','while','with','would','your','youre','dont','cant','really','think','know','going','something','someone','people']);
function theme(t) {
  const w = String(t || '').toLowerCase().replace(/[^a-z\s]/g, ' ').split(/\s+/)
    .filter(x => x.length > 4 && !STOP.has(x));
  const uniq = Array.from(new Set(w)).sort((a, b) => b.length - a.length).slice(0, 4);
  return uniq.sort().join(' ') || 'unclassified';
}

const rows = [];
$input.all().forEach(it => {
  const items = it.json.items || [];
  if (!items.length) return;
  // Recover which video this response belongs to.
  let meta = {};
  try { meta = $('Comments: Plan Fetch').all().map(x => x.json)
    .find(m => items[0] && items[0].snippet && m.videoId === items[0].snippet.videoId) || {}; } catch (e) {}
  const isNCO = meta.brand === 'NCO Forge';

  items.forEach(th => {
    const top = ((th.snippet || {}).topLevelComment || {}).snippet || {};
    const id = String(th.id || '');
    if (!id || seen.has(id)) return;
    const when = top.publishedAt ? Date.parse(top.publishedAt) : 0;
    if (when && when < cutoff) return;
    const text = String(top.textDisplay || top.textOriginal || '');
    const cls = classify(text);
    if (cls === 'Noise') return;
    const likes = Number(top.likeCount || 0);
    rows.push({ fields: {
      'Signal ID': id,
      'Brand': meta.brand || 'The Quiet Operator',
      'Source': 'YouTube',
      'Content ID': meta.contentId || '',
      'Raw Text': text.slice(0, 4000),
      'Author': String(top.authorDisplayName || ''),
      'Engagement': likes,
      'Classification': cls,
      'Routed To': route(cls, isNCO),
      'Theme': theme(text),
      'Priority': likes + (cls === 'Recurring pain' ? 10 : 0) + (cls === 'Story' ? 8 : 0) + (cls === 'Tool request' ? 6 : 0),
      'Status': 'New',
      'Captured At': new Date(when || Date.now()).toISOString()
    } });
  });
});

if (!rows.length) return [];
rows.sort((a, b) => (b.fields.Priority || 0) - (a.fields.Priority || 0));
const out = [];
for (let i = 0; i < rows.length; i += 10) {
  out.push({ json: { captured: rows.length, body: { typecast: true, records: rows.slice(i, i + 10) } } });
}
return out;

// Asset Type is a closed vocabulary and the script writer's Idea filter matches
// it as an exact string, so a drifted spelling here would put a Short straight
// back into the long-form queue without anything erroring. The value below is a
// literal, so an unknown one can only mean this node was edited wrong. Fail loud.
const ASSET_TYPES = ['Flagship', 'Short'];
function assetType(v) {
  const raw = String(v == null ? '' : v).trim();
  const hit = ASSET_TYPES.filter(t => t.toLowerCase() === raw.toLowerCase())[0];
  if (!hit) throw new Error('Unknown Asset Type "' + raw + '". Allowed: ' + ASSET_TYPES.join(', '));
  return hit;
}

// A winning post should not just sit there being a winning post. The whole
// argument for measuring is that the measurement changes what gets made next.
const TQO = 'tqo_content', NCO = 'nco_content';
const TQO_REF = '2GtmrFcTNqVMbddh', NCO_REF = 'DSH1tn4TZjzAEKxp';
const rows = [];

try {
  $('Analytics: Build Performance Rows').all().forEach(it => {
    ((it.json.body || {}).records || []).forEach(r => {
      const f = r.fields || {};
      const score = Number(f['Outlier Score'] || 0);
      if (!f['Winner'] || score < 1.5) return;
      const isNCO = f['Brand'] === 'NCO Forge';
      const cid = f['Content ID'] || f['Platform ID'];
      const days = f['Days Since Post'];
      // Too early to call. A three-day-old video outperforming the median is
      // often just the subscriber bump, not a real signal about the idea.
      if (days != null && days < 7) return;

      rows.push({
        tableId: isNCO ? NCO : TQO, tableRef: isNCO ? NCO_REF : TQO_REF,
        fields: {
          'Topic': cid + ' RE-EXPANSION',
          'Idea': 'RE-EXPANSION. ' + cid + ' is running at ' + score + 'x this brand\'s median at ' +
                  days + ' days. Build the deeper episode the winning one implied rather than a sequel to it. ' +
                  'Go back to the Content Primitives rows for ' + cid + ', find the highest-strength primitive ' +
                  'that no asset was built from, and make that the spine. Do not restate the original.',
          'Status': 'Idea',
          'Channel': f['Brand'],
          'Asset Type': assetType('Flagship'),
          'Idea Score': 88,
          'Idea Score Breakdown': 'Auto-scored 88 from measured performance, not from judgement about the topic. ' +
                  'Outlier ' + score + 'x median at ' + days + ' days on ' + f['Platform'] + '. ' +
                  'Confirm the idea is worth a second episode before producing; a strong hook can carry a thin topic once.',
          'Routing': 'Flagship candidate'
        }
      });
    });
  });
} catch (e) { return []; }

if (!rows.length) return [];
return rows.map(r => ({ json: { tableId: r.tableId, tableRef: r.tableRef, body: {
  performUpsert: { fieldsToMergeOn: ['Topic'] }, typecast: true, records: [{ fields: r.fields }]
} } }));

// Asset Type is a closed vocabulary and the script writer's Idea filter matches
// it as an exact string, so a drifted spelling here would put a Short straight
// back into the long-form queue without anything erroring. The value below is a
// literal, so an unknown one can only mean this node was edited wrong. Fail loud.
const ASSET_TYPES = ['Flagship', 'Short'];
function assetType(v) {
  const raw = String(v == null ? '' : v).trim();
  const hit = ASSET_TYPES.filter(t => t.toLowerCase() === raw.toLowerCase())[0];
  if (!hit) throw new Error('Unknown Asset Type "' + raw + '". Allowed: ' + ASSET_TYPES.join(', '));
  return hit;
}

// One person asking a question is a comment. Three people asking the same
// question is a gap in the content, and that is what this counts.
const THRESHOLD = 3;
const TQO = 'tqo_content', NCO = 'nco_content';
const TQO_REF = '2GtmrFcTNqVMbddh', NCO_REF = 'DSH1tn4TZjzAEKxp';

const signals = [];
try {
  $('Comments: Classify and Route').all().forEach(it => {
    ((it.json.body || {}).records || []).forEach(r => signals.push(r.fields || {}));
  });
} catch (e) { return []; }
try {
  ($('Signals: Fetch Recent').first().json.records || []).forEach(r => signals.push(r.fields || {}));
} catch (e) { /* first run */ }
if (!signals.length) return [];

const groups = {};
signals.forEach(s => {
  const t = String(s['Theme'] || '').trim();
  const cls = String(s['Classification'] || '');
  if (!t || t === 'unclassified') return;
  if (cls === 'Praise' || cls === 'Noise') return;
  const key = (s['Brand'] || '') + '||' + t;
  groups[key] = groups[key] || { brand: s['Brand'], theme: t, n: 0, weight: 0, examples: [], routes: {}, cls: {} };
  const g = groups[key];
  g.n += 1;
  g.weight += Number(s['Priority'] || 0);
  g.routes[s['Routed To'] || 'None'] = (g.routes[s['Routed To'] || 'None'] || 0) + 1;
  g.cls[cls] = (g.cls[cls] || 0) + 1;
  if (g.examples.length < 3) g.examples.push(String(s['Raw Text'] || '').slice(0, 220));
});

const out = [];
Object.values(groups).forEach(g => {
  if (g.n < THRESHOLD) return;
  const isNCO = g.brand === 'NCO Forge';
  const topRoute = Object.entries(g.routes).sort((a, b) => b[1] - a[1])[0][0];
  const topCls = Object.entries(g.cls).sort((a, b) => b[1] - a[1])[0][0];
  // Score from evidence, not from enthusiasm: recurrence carries most of it.
  const score = Math.min(92, 55 + g.n * 6 + Math.min(15, Math.round(g.weight / 4)));
  out.push({ json: { tableId: isNCO ? NCO : TQO, tableRef: isNCO ? NCO_REF : TQO_REF, body: {
    performUpsert: { fieldsToMergeOn: ['Topic'] }, typecast: true,
    records: [{ fields: {
      'Topic': 'AUDIENCE: ' + g.theme,
      'Idea': 'From the audience, not from a brainstorm. ' + g.n + ' separate ' + topCls.toLowerCase() +
              ' signals on this theme. Representative comments:\n\n' +
              g.examples.map((e, i) => (i + 1) + '. ' + e).join('\n') +
              '\n\nAnswer the thing they actually asked, in their words, before adding anything of your own.',
      'Status': 'Idea',
      'Channel': g.brand,
      'Show': (['NCO School', 'NCO Confessions', 'Hard Call', 'The Forge', 'The Quiet Advantage', 'The AI Shift'].indexOf(topRoute) >= 0) ? topRoute : undefined,
      'Asset Type': assetType((topRoute === 'Response Short') ? 'Short' : 'Flagship'),
      'Idea Score': score,
      'Idea Score Breakdown': 'Recurrence ' + g.n + ' signals, engagement weight ' + g.weight +
              ', dominant classification ' + topCls + ', routed to ' + topRoute + '. ' +
              'Scored from measured audience repetition rather than from how interesting the topic sounds.',
      'Routing': score >= 85 ? 'Flagship candidate' : 'Produce'
    } }]
  } } });
});
return out;

// TRIGGER DIET (20 Aug 2026): fed by the 3h Pipeline Pass; run only two passes a day
// to keep the repurpose lane's Airtable reads inside the free monthly quota.
const __h=Number($now.setZone('America/New_York').hour);
if(__h!==9&&__h!==21)return [];

// Repurpose watches folders. One folder per platform, one Repurpose workflow
// per folder, each pointed at its own destination. The pipeline's job is to put
// the right artifact in the right folder and then stop.
//
// Folders created 9 Aug 2026 under your existing Repurpose folder
// (1pmP5AK5kAasX-LYc49z0SEbh8Is8govV). Each one still needs a Repurpose
// workflow pointed at it on their side; a folder nobody is watching just
// quietly accumulates files.
const FOLDERS = {
  'TikTok':          { id: '1_RSYP3HZcJDHBeQqQNluwwaxLeznBxyK', video: true  },
  'Instagram':       { id: '1jBzmtaOC-thLLdNuXxEPr4lvMgtlHMVw', video: true  },
  'Facebook':        { id: '1Ssp3NYBUH8ip0yUNenBNwDsCvzccrgMN', video: true  },
  'YouTube Shorts':  { id: '1-ozIeBjXGCzscEa_o7nVahO93CxYkByc', video: true  },
  'Pinterest':       { id: '1s28lHH8PMqk3eLLHEm4HjTHd2IKPLJdR', video: true  },
  'LinkedIn':        { id: '1M4-F4ss-hj1qxvBWxOvnvL6IQize4xwX', video: false },
  'X':               { id: '1VZvobCcMSEQYnZ2gnc_c-rIhoF2qGuca', video: false },
  'Threads':         { id: '1BbEuKA4IkUC3nQpyntNIuYqVsXHlP8pI', video: false }
};

// Not routed here on purpose. The newsletter goes out through MailerLite in the
// brief lane, and Community, Blog and Podcast have no automated destination
// yet, so their slots stay Pending rather than being marked done by a folder
// drop that never happens.
const UNROUTED = ['Newsletter', 'Community', 'Blog', 'Podcast', 'YouTube'];

return [{ json: { folders: FOLDERS, unrouted: UNROUTED } }];

// One drop per Publishing slot. Not collapsed by asset, because each platform
// now has its own watched folder and therefore its own copy of the file.
//
// 2026-09-23: reads n8n data table at_tqo_publishing (one item per Pending row)
// instead of the Airtable API. The table stores scheduled_for as text, so the
// "time has passed" test lives here, not in the query. An unparsable or empty
// time is treated as not due: a slot nobody scheduled is not posted early.
const cfg = $('Repurpose: Config').first().json;
const now = Date.now();
const due = [];
for (const item of $input.all()) {
  const r = item.json || {};
  if (r.id === undefined || r.id === null) continue;
  const when = Date.parse(String(r.scheduled_for || ''));
  if (!Number.isFinite(when) || when > now) continue;
  const plat = String(r.platform || '');
  const dest = cfg.folders[plat];
  if (!dest) continue;               // unrouted platform, slot stays Pending
  const assetId = String(r.asset_id || '');
  if (!assetId) continue;
  due.push({ when, json: {
    slotId: r.id,
    assetId,
    contentId: String(r.content_id || ''),
    brand: String(r.brand || ''),
    platform: plat,
    folderId: dest.id,
    needsVideo: dest.video === true,
    priorPostedAt: String(r.posted_at || '')
  } });
}
// Oldest first, ten a cycle, so a backlog drains without ever making one
// execution carry a hundred file uploads.
due.sort((a, b) => a.when - b.when);
return due.slice(0, 10).map(d => ({ json: d.json }));

// Same closed vocabulary as the row builders, but this value is data read back
// off an existing row rather than a literal, so an odd value is a data problem
// and must not take the pipeline down. Fix the casing and spacing, keep anything
// unrecognized as it stands, and default an untyped row to Flagship.
const ASSET_TYPES = ['Flagship', 'Short'];
function assetType(v) {
  const raw = String(v == null ? '' : v).trim();
  if (!raw) return 'Flagship';
  const hit = ASSET_TYPES.filter(t => t.toLowerCase() === raw.toLowerCase())[0];
  return hit || raw;
}

// A fresh Idea row used to reach OS 30 missing five fields and get held for
// things nobody had told it to fill. The pipeline knows all of them at script
// time, so it fills them here rather than waiting to refuse later.
//
// Human Review is deliberately NOT set. That gate is the one place a human has
// to look at the thing before it goes out, and a pipeline that ticks its own
// approval box is not a gate.
const ctx = $('Show Context: Script').first().json;
const row = $('One Idea at a Time').first().json;
const f   = row.fields || row;
const sc  = $('Originality Scan').first().json;

// The package, when this episode has one, comes from Package: Context and not
// from the row, because the row item was read before the lock was written. A
// locked headline and subject were chosen against the title the audience will
// actually see, so recomputing them from the finished script would throw that
// away. Wrapped, because the packaging lane does not run on every path.
let pkg = { packageLocked: false };
try { pkg = $('Package: Context').first().json || pkg; } catch (e) { /* no packaging lane on this path */ }

const isNCO = ctx.show === 'NCO';
const script = String(sc.script || f.Script || '');
const title  = String(sc.title || f['Video Title'] || f.Topic || '');
let desc     = String(sc.description || f.Description || '');

// 1. Disclosure. Set the flag only after making it true.
const DISCLOSURE = 'Presented with a synthetic voice and synthetic likeness of Terrance Veal, used with his consent.';
const HAS_DISCLOSURE = /synthetic voice and synthetic likeness|used with his consent|AI assistance|AI-assisted|scripted and narrated with AI/i;
if (!HAS_DISCLOSURE.test(desc)) {
  desc = DISCLOSURE + '\n\n' + desc.trim();
}

// 2. Claim validity. Anything anchored to a named model, a year or a headline
// goes stale fast. A principle about judgment does not.
const VOLATILE = /(20\d\d|GPT-?\d|Claude \d|Gemini|last (month|quarter|week)|this (month|quarter|year)|recently announced|just released|new model|currently)/i;
const validity = VOLATILE.test(script) ? 'Frequently Changing' : 'Slowly Changing';
const days = validity === 'Frequently Changing' ? 90 : 365;
const recheck = new Date(Date.now() + days * 86400000).toISOString().slice(0, 10);

// 3. Thumbnail backdrop. The broll array is already ordered concrete nouns, so
// its first entry is the most searchable subject the episode has. Only used
// when no package locked a subject first.
let broll = sc.broll;
if (Array.isArray(broll)) broll = broll.join(', ');
const subject = String(broll || '').split(',')[0].trim()
  || (isNCO ? 'soldier briefing room low light' : 'professional desk window evening');

// 4. Thumbnail headline. Word ceiling from the brand spec: TQO 5, NCO Forge 4.
// Same fallback rule: a locked headline wins, this is the unpackaged path.
const cap = isNCO ? 4 : 5;
let head = title.replace(/[—–]/g, ' ').replace(/[^A-Za-z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim();
const STOP = new Set(['the','a','an','of','to','in','on','at','for','with','and','or','your','you','that','this','is','are','what','how','why']);
let words = head.split(' ').filter(Boolean);
if (words.length > cap) {
  const strong = words.filter(w => !STOP.has(w.toLowerCase()));
  words = (strong.length >= 2 ? strong : words).slice(0, cap);
}
head = words.join(' ').toUpperCase();

const locked = pkg && pkg.packageLocked === true;
const finalSubject = (locked && pkg.primarySubject) ? pkg.primarySubject : subject;
const finalHead = (locked && pkg.thumbnailHeadline) ? pkg.thumbnailHeadline : head;

return [{ json: {
