const DISCLOSURE = 'Presented with a synthetic voice and synthetic likeness of Terrance Veal, used with his consent.';
const HAS_DISCLOSURE = /synthetic voice and synthetic likeness|used with his consent|AI assistance|AI-assisted|scripted and narrated with AI/i;
if (!HAS_DISCLOSURE.test(desc)) {
  desc = DISCLOSURE + '\n\n' + desc.trim();
}
// QUALITY LAW rev2 check 8 (proof on screen) note: description unchanged by law;
// law enforcement lives in QC. This node's contract stays the C4 disclosure.

// Bounds the render poll loop. Without a ceiling, a job the worker never
// finishes cycles Wait 60s -> Check Render Status forever: the execution never
// ends and the Airtable row stays claimed as Rendering.
//
// This node used to throw on the limit. It no longer does. Throwing killed the
// run at the exact moment the row was still claimed, so a give-up left the
// episode locked as Rendering until the Reaper swept it up to three hours
// later. Now it emits a flag, the failure path releases the claim, and THEN
// the run stops with an error. The stop is just as loud; the row is free.
//
// ON THE LIMIT, AND WHY IT IS 75
//
// This worker reports status 'running' with the message 'Render queued' for the
// ENTIRE job. It never says 'rendering'. The message is a static label, not a
// progress signal, so a long run of 'Render queued' is not evidence of a jam.
//
// Measured runs, 9 Aug 2026:
//   1391 - FAILED at 5 polls. ffmpeg moov-atom error on an undecodable clip.
//          Failures abort early, so a fast exit is not the yardstick.
//   1401 - SUCCEEDED. 33 polls, 33m52s, 66 MB mp4, 45 clips.
//   1406 - SUCCEEDED. 33 polls, 32m44s.
//   1412 - SUCCEEDED. 40 polls, 40m54s.
//
// That last one matters. The old cap was 45. A healthy render used 40 of it.
// Five polls of headroom on a job that varies by eight minutes between runs is
// not a safety net, it is a coin toss - and killing work that was going to
// succeed is worse than the hang the cap exists to prevent, because it looks
// like a fault and is not one. 75 is roughly double the longest observed
// healthy render and still well inside the 3-hour Reaper window.
//
// If renders start regularly exceeding 60 polls, the worker is the thing to
// look at, not this number.
//
// Override per brand by setting maxPolls on Show Context: Render.
const FALLBACK_MAX_POLLS = 75;

let MAX_POLLS = FALLBACK_MAX_POLLS;
try {
  const ctx = $('Show Context: Render').first().json;
  if (ctx && Number.isFinite(Number(ctx.maxPolls)) && Number(ctx.maxPolls) > 0) {
    MAX_POLLS = Number(ctx.maxPolls);
  }
} catch (e) {
  // Context not reachable on this path. Fall back rather than fail: a missing
  // context value must not be the thing that kills a healthy render.
}

const m = ($json.movie || {});
const status = String(m.status || 'unknown');
const project = String(m.project || 'unknown');
const overBudget = $runIndex >= MAX_POLLS;

const giveUpReason = overBudget
  ? ('gave up after ' + MAX_POLLS + ' polls (~' + MAX_POLLS + ' min). Last status: ' + status
     + ' / ' + String(m.message || 'no message') + '. This worker does not report progress, so the '
     + 'message says nothing about how far it got. Healthy renders have taken 33 to 40 polls, so this '
     + 'is roughly twice the longest known-good run. Check 129.80.78.29:8080: disk space first (a full '
     + 'volume accepts jobs and never finishes them, and truncates clip downloads into moov atom '
     + 'errors), then whether the render process is alive, then /data/work for stale job directories. '
     + 'If the episode is genuinely long, raise maxPolls on Show Context: Render rather than treating '
     + 'it as a fault.')
  : null;

return $input.all().map(item => ({
  json: Object.assign({}, item.json, {
    giveUp: overBudget,
    giveUpReason,
    pollsUsed: $runIndex,
    maxPolls: MAX_POLLS,
  }),
}));

// Releases the Airtable claim when a render fails, before the run stops.
//
// Two entries reach this node:
//   1. IF Render Failed out 0 - the worker reported movie.status 'error'.
//   2. Render: Over Budget? out 0 - the poll loop hit its ceiling.
// Both leave the row in Rendering with a live claim. Release first, stop second,
// so a give-up never leaves the row locked (that cost six weeks in June).
//
// RETRY CAP (added 12 Aug 2026)
// A row that fails for a persistent reason (undecodable clip, worker fault) used
// to bounce back to Queued forever, re-billing full ElevenLabs TTS every tick.
// Now each failure increments 'Render Attempts'. Below the cap the row returns to
// Queued and retries next tick; AT the cap it parks at Status 'Blocked' so it
// stops re-rendering and re-billing until a human clears the root cause. The
// counter is reset to 0 on a successful render (Mark Ready + Save URL). This is
// separate from 'Correction Attempts', which the QC/packaging loop owns.
const MAX_RENDER_ATTEMPTS = 3;

const ctx = $('Show Context: Render').first().json;
const row = $('Process Each Video').item.json;
const m = ($json.movie || {});

const project = String(m.project || $json.project || 'unknown');

const prevAttempts = Number(
  (row.fields && row.fields['Render Attempts']) ?? row['Render Attempts'] ?? 0
) || 0;
const attempts = prevAttempts + 1;
const blocked = attempts >= MAX_RENDER_ATTEMPTS;
const target = blocked ? 'Blocked' : 'Queued';

let reason = $json.giveUpReason;
if (!reason && String(m.status || '') === 'error') {
  reason = 'worker reported status error: ' + String(m.message || 'no message');
}
if (!reason) {
  reason = String(($json.error && $json.error.message) || $json.message || 'render failed');
}

const note = blocked
  ? ('Render failed ' + attempts + ' times (cap ' + MAX_RENDER_ATTEMPTS + '); parked at Blocked at '
     + $now.toISO() + '. Project ' + project + '. Last reason: ' + String(reason).slice(0, 500)
     + ' Not re-queued: a persistent failure was re-billing TTS every tick. Fix the root cause '
     + '(usually the render worker at 129.80.78.29 or a bad clip), then set Status back to Queued and Render Attempts to 0 by hand.')
  : ('Claim released after a failed render at ' + $now.toISO() + '. Project ' + project
     + '. Attempt ' + attempts + ' of ' + MAX_RENDER_ATTEMPTS + '. Reason: ' + String(reason).slice(0, 500)
     + ' Row returned to Queued and is eligible for the next render tick.');

return [{
  json: {
    tableId: ctx.tableId,
    tableRef: ctx.tableRef,
    recordId: row.id,
    project,
    attempts,
    blocked,
    reason: String(reason).slice(0, 600),
    body: {
      typecast: true,
      records: [{
        id: row.id,
        fields: {
          Status: target,
          'System Status': '',
          'Render Attempts': attempts,
          'Last Feedback': note,
        },
      }],
    },
  },
}];

// Resolve the YouTube video id (whichever brand uploaded) and the Drive file id
// of the composed thumbnail, both non-fatally. Feeds the thumbnails.set branch.
let videoId = '';
try { videoId = String($('Upload to YouTube').item.json.uploadId || ''); } catch (e) {}
if (!videoId) { try { videoId = String($('Upload to YouTube (NCO Forge)').item.json.uploadId || ''); } catch (e) {} }
let thumbFileId = '';
try { thumbFileId = String($('Upload Thumbnail').item.json.id || ''); } catch (e) {}
return [{ json: { videoId, thumbFileId, canSet: Boolean(videoId && thumbFileId) } }];

