const out=[];for(const it of $input.all()){const j=it.json||{};const recs=((j.body||{}).records)||[];for(const r of recs){out.push({json:{__table:j.tableId,__tableRef:j.tableRef,__id:r.id,...(r.fields||{})}});}}
return out;

// Break before you spend. A ping that cannot be verified is refused BEFORE it
// costs an API call, and a sale_id taken from an untrusted body never reaches a
// URL path unchecked. Rebuilt 2026-09-08: the previous guard compared seller_id
// against $env.GUMROAD_SELLER_ID, which can never pass on n8n Cloud, because
// Cloud has no environment to set and blocks $env inside Code nodes.
// Corrected the same day, before the first proving test: Gumroad ids are base64
// with padding and end in two equals signs (the API documentation's examples do,
// B28UKN-dvxYabdavG97Y-Q==). The first regex here rejected "=" outright and would
// have refused every real sale at the door. Up to two trailing "=" are now part
// of a plausible id; nothing else about the check changed.
const b = $json.body || $json.query || $json;
const raw = String(b.sale_id || b.order_number || '').trim();

if (!raw) {
  throw new Error('REFUSED before any work: this Gumroad ping carried no sale_id, so there is nothing to verify against Gumroad. Nothing was written. Payload keys seen (' + Object.keys(b).length + '): ' + (Object.keys(b).join(', ') || '(none)') + '.');
}
if (!/^[A-Za-z0-9_-]{1,64}={0,2}$/.test(raw)) {
  throw new Error('REFUSED before any work: sale_id is not a plausible Gumroad id, so it was NOT placed into an API URL. Length ' + raw.length + ', starts "' + raw.slice(0, 4) + '". Nothing was written.');
}

return [{ json: { saleId: raw, pingSeenAt: new Date().toISOString(), pingBody: b } }];

// Script Gate: Quality (added 15 Sep 2026, on Tee's instruction that scripts get
// checked before anything downstream spends on them).
//
// Everything here is measured, never judged: the Script Doctor and the
// Originality Scan already judged, and this node decides whether their answers
// clear the floor. A draft that fails lands as Error with the reasons in
// qc_findings and last_feedback (ruled by Tee 22 Sep 2026: the status
// vocabulary is closed, and Script Hold, used here from 15 to 22 Sep, was
// outside it and read by nothing). Promote only picks Scripted rows that Tee
// has released, so no narration is bought for a failed draft. Tee clears an
// Error by hand: set status to Scripted to accept it as is, or back to Idea to
// have it written again.
//
// The two numeric floors below are constants because they are rulings, not
// measurements. Change them here, with a date, never per episode.
const WORD_FLOOR = 1200;      // the brief's own hard floor
const WORD_CEILING = 2400;    // the brief says 2000; 20 percent of slack, then it is a runaway
const DOCTOR_FLOOR = 70;      // out of 100; QC ships at 80, the doctor holds at 70
const RHYTHM_FLOOR = 50;      // originality scan, rhythm and tells
const SIMILARITY_FLOOR = 50;  // originality scan, overlap with the back catalogue
const BROLL_FLOOR = 6;        // the brief asks 8 to 12; under 6 starves the b-roll planner

const d = $json;
// The two pass writer's own numbers ride in Build Doctor Prompt's original, on
// whichever branch ran, so the report can say what the first draft measured.
const o = $('Build Doctor Prompt').first().json.original || {};
let devonNote = 'no recall step ran';
try { devonNote = String($('DEVON Recall: Merge').first().json.devonRecallNote || 'recall ran and said nothing'); } catch (e) { devonNote = 'recall node not reached: ' + e.message; }
const script = String(d.script || '');
const words = script.split(/\s+/).filter(Boolean).length;
const dashesIn = (s) => (String(s || '').match(/[—–]/g) || []).length;
const dashes = dashesIn(script) + dashesIn(d.title) + dashesIn(d.description);
const broll = String(d.broll || '').split(',').map(s => s.trim()).filter(Boolean);
const verdict = String(d.doctorVerdict || '');
const score = Number(d.doctorScore) || 0;
const rhythm = Number(d.rhythmScore);
const similarity = Number(d.similarityScore);

const failures = [];
if (!script.trim()) failures.push('the script is empty');
if (words < WORD_FLOOR) failures.push('script is ' + words + ' words, under the floor of ' + WORD_FLOOR);
if (words > WORD_CEILING) failures.push('script is ' + words + ' words, over the ceiling of ' + WORD_CEILING);
if (dashes) failures.push(dashes + ' em or en dash(es) in the script, title or description');
if (verdict === 'UNCHECKED' || !verdict) failures.push('the script doctor did not run (verdict ' + (verdict || 'missing') + ')');
else if (score < DOCTOR_FLOOR) failures.push('script doctor scored it ' + score + '/100, under the floor of ' + DOCTOR_FLOOR);
if (Number.isFinite(rhythm) && rhythm < RHYTHM_FLOOR) failures.push('originality rhythm ' + rhythm + '/100, under the floor of ' + RHYTHM_FLOOR);
if (Number.isFinite(similarity) && similarity < SIMILARITY_FLOOR) failures.push('originality similarity ' + similarity + '/100, under the floor of ' + SIMILARITY_FLOOR + ' (too close to an earlier episode)');
if (broll.length < BROLL_FLOOR) failures.push('only ' + broll.length + ' b-roll phrase(s), under the floor of ' + BROLL_FLOOR);
if (!String(d.title || '').trim()) failures.push('no title');

// The TQO episode promises, ruled by Tee 23 Sep 2026 to match the home page: a
// learning objective inside the first 30 seconds, a checklist of 3 to 5 steps,
// a close that asks one question for the comments, never a like or subscribe
// ask, never the retired free audit, never the urgency opener. Measured, not
// judged, and TQO only because NCO was not ruled. The windows are words, not
// seconds: 70 words is 30 seconds at the 140 words a minute that Show Context:
// Render targets. The real narration pace is unmeasured.
const LO_WINDOW = 70;
const CLOSE_WINDOW = 60;
let promises = '';
if ($('Show Context: Script').first().json.show !== 'NCO') {
  const tokens = script.split(/\s+/).filter(Boolean);
  const norm = (s) => String(s || '').toLowerCase().replace(/[^a-z0-9\s]/g, ' ').split(/\s+/).filter(Boolean).join(' ');
  const opening = tokens.slice(0, LO_WINDOW).join(' ');
  const closing = tokens.slice(-CLOSE_WINDOW).join(' ');
  const lo = norm(d.learningObjective);
  const loOk = !!lo && (' ' + norm(opening) + ' ').includes(' ' + lo + ' ');
  const steps = Array.isArray(d.checklist) ? d.checklist.map(s => String(s).trim()).filter(Boolean) : [];
  const askOk = /\?/.test(closing) && /\bcomments?\b/i.test(closing);
  const promiseDashes = dashesIn(d.learningObjective) + dashesIn(steps.join(' '));
  if (!lo) failures.push('no learning objective returned');
  else if (!loOk) failures.push('the learning objective is not spoken word for word inside the first ' + LO_WINDOW + ' words (30 seconds)');
  if (steps.length < 3 || steps.length > 5) failures.push('checklist has ' + steps.length + ' step(s); every episode promises 3 to 5');
  if (promiseDashes) failures.push(promiseDashes + ' em or en dash(es) in the learning objective or checklist, which dash repair does not reach');
  if (!askOk) failures.push('the last ' + CLOSE_WINDOW + ' words ask no question for the comments');
  if (/before it(?:'|’)?s too late|before it is too late/i.test(opening)) failures.push('opens on the urgency line before it is too late, which the channel dropped');
  if (/\blike and subscribe\b/i.test(script) || /\bsubscribe\b/i.test(closing + '\n' + String(d.description || ''))) failures.push('asks the viewer to like or subscribe');
  if (/jobsecurityaudit|\bfree (?:job security )?audit\b|quietleverage\.netlify\.app|tqohq\.online|\bfree leverage audit\b/i.test([script, d.title, d.description, steps.join(' ')].join('\n'))) failures.push('points to the retired free audit');
  promises = '  promises: objective ' + (loOk ? 'inside ' + LO_WINDOW + ' words' : 'missing') + ' | checklist ' + steps.length + ' step(s) | closing question ' + (askOk ? 'yes' : 'no');
}

const stamp = new Date().toISOString();
const status = failures.length ? 'Error' : 'Scripted';
const report = [
  'SCRIPT GATE ' + (failures.length ? 'FAIL' : 'PASS') + ' at ' + stamp,
  '  words ' + words + ' | dashes ' + dashes + ' | doctor ' + (verdict || '?') + ' ' + score + '/100 | rhythm ' + (Number.isFinite(rhythm) ? rhythm : '?') + ' | similarity ' + (Number.isFinite(similarity) ? similarity : '?') + ' | b-roll ' + broll.length,
  ...(promises ? [promises] : []),
  '  writer: draft ' + (o.draftWords ?? '?') + ' words, expansion ' + (o.expansion || 'not recorded') + ' (two pass writer, ruled 15 Sep 2026)',
  '  devon: ' + devonNote,
  ...(failures.length
    ? ['', 'FAILED BECAUSE:', ...failures.map(f => '  - ' + f), '', 'Set status to Scripted to accept it as is, or to Idea to write it again.']
    : ['', 'Cleared for Promote.'])
].join('\n');

return [{ json: {
  ...d,
  status,
  gateFailures: failures,
  gateWords: words,
  gateReport: report,
  gateReason: failures.length ? ('SCRIPT GATE FAILED ' + stamp + '. ' + failures.join('; ') + '. Set status to Scripted to accept it as is, or to Idea to write it again.') : '',
  lastFeedback: String(d.lastFeedback || '') + '\n\n' + report
} }];

// Script: Needs Expansion? (added 15 Sep 2026). The two pass writer, ruled by
// Tee on an inline card after five measured undershoots on the real TQO prompt:
// 894, 798, 1055, 1059 and 848 words against a floor of 1200. One pass asks for
// 1800 to 2200 and lands short; a second pass that is handed the draft and told
// to lengthen it is the cheapest fix that does not lower the floor.
//
// This node only decides and prepares. A draft at or over EXPAND_BELOW goes
// straight to the doctor with expansion 'not needed'. A short one carries an
// expandBody for Expand Script (Cerebras); the IF node after this reads
// needsExpansion. The system prompt and the brief are reused verbatim from the
// first pass so the second pass is held to the same voice and the same rules.
const EXPAND_BELOW = 1200;   // the gate's WORD_FLOOR; keep the two equal
const TARGET_LOW = 1800;
const TARGET_HIGH = 2200;

const d = $json;
const script = String(d.script || '');
const words = script.split(/\s+/).filter(Boolean).length;
if (words >= EXPAND_BELOW) {
  return [{ json: { ...d, draftWords: words, needsExpansion: false, expansion: 'not needed at ' + words + ' words' } }];
}

const budget = $('Token Budget: Script').first().json.body || {};
const msgs = Array.isArray(budget.messages) ? budget.messages : [];
const system = msgs.filter(m => m.role === 'system').map(m => String(m.content || '')).join('\n\n');
const brief = msgs.filter(m => m.role === 'user').map(m => String(m.content || '')).join('\n\n');
const draft = { title: d.title || '', script, description: d.description || '', tags: d.tags || '', broll: d.broll || '' };

const user = [
  'The draft below came back at ' + words + ' words. The brief requires at least ' + EXPAND_BELOW + ' words and the target is ' + TARGET_LOW + ' to ' + TARGET_HIGH + '.',
  'Expand it to between ' + TARGET_LOW + ' and ' + TARGET_HIGH + ' words. Rules for the expansion:',
  '- Keep the hook, the first two sentences, exactly as written.',
  ...(d.learningObjective ? ['- Keep the learning objective word for word and inside the first 70 words, and add nothing before it. It reads: ' + d.learningObjective] : []),
  ...(Array.isArray(d.checklist) && d.checklist.length ? ['- Keep the checklist steps word for word and in order, with none added or removed. Lengthen around them, not inside them. They read: ' + d.checklist.map((s, i) => (i + 1) + '. ' + s).join(' ')] : []),
  '- Keep every section and its order. Lengthen each one with a concrete example, a mechanism the viewer can follow, or a number the viewer can check. Where the draft has no verifiable number, add a worked example instead of inventing a statistic.',
  '- Keep the title, description, tags and broll unchanged unless the expansion makes one of them wrong.',
  '- Never use an em dash or an en dash anywhere. Use a comma, a full stop or the word to.',
  '- Do not summarise, compress or drop anything that is in the draft.',
  'Return only a JSON object in exactly this shape: {"title": "...", "script": "...", "description": "...", "tags": "...", "broll": ["...", "..."]}.',
  '',
  'THE ORIGINAL BRIEF:',
  brief,
  '',
  'THE DRAFT TO EXPAND (JSON):',
  JSON.stringify(draft)
].join('\n');

const expandBody = {
  model: budget.model || 'gpt-oss-120b',
  messages: [ ...(system ? [{ role: 'system', content: system }] : []), { role: 'user', content: user } ],
  max_completion_tokens: budget.max_completion_tokens || 10000,
  reasoning_effort: 'medium',
  response_format: { type: 'json_object' }
};

return [{ json: { ...d, draftWords: words, needsExpansion: true, expandBody } }];

// Parse Expanded Script (added 15 Sep 2026). Returns the same shape Parse Script
// JSON returns, so Build Doctor Prompt needs no rewiring. If the expansion cannot
// be used, the first draft goes on unchanged with the reason in the expansion
// field: the gate then holds it for length and the reason lands in
// last_feedback. An expansion that fails never costs the draft.
const prev = $('Script: Needs Expansion?').first().json;
const { expandBody, needsExpansion, ...base } = prev;
const draftWords = Number(prev.draftWords) || 0;

function keepDraft(reason) {
  return [{ json: { ...base, expansion: 'failed, first draft kept: ' + reason, expandedWords: draftWords } }];
}

const out = $json || {};
if (out.stop_reason === 'max_tokens' || out.choices?.[0]?.finish_reason === 'length') return keepDraft('the expansion was truncated at the token ceiling');
let text = out.choices?.[0]?.message ? String(out.choices[0].message.content ?? '') : String(out.content?.[0]?.text ?? '');
if (!text.trim()) return keepDraft('the expansion returned no text');

text = text.replace(/```json/gi, '```');
const start = text.indexOf('{');
const end = text.lastIndexOf('}');
if (start === -1 || end === -1) return keepDraft('the expansion was not a JSON object');
let parsed;
try { parsed = JSON.parse(text.slice(start, end + 1)); } catch (e) { return keepDraft('the expansion JSON did not parse: ' + e.message); }

const script = String(parsed.script || '');
const words = script.split(/\s+/).filter(Boolean).length;
if (words <= draftWords) return keepDraft('the expansion came back at ' + words + ' words, no longer than the ' + draftWords + ' word draft');

return [{ json: {
  ...base,
  title: String(parsed.title || base.title || ''),
  script,
  description: String(parsed.description || base.description || ''),
  tags: Array.isArray(parsed.tags) ? parsed.tags.join(', ') : String(parsed.tags ?? base.tags ?? ''),
  broll: Array.isArray(parsed.broll) ? parsed.broll.map(s => String(s).trim()).filter(Boolean).join(', ') : String(parsed.broll || base.broll || ''),
  expansion: 'expanded from ' + draftWords + ' to ' + words + ' words',
  expandedWords: words
} }];

// Dash Repair: Needs? (added 15 Sep 2026). The gate holds any script, title or
// description carrying an em dash or an en dash, because the voice profile
// forbids them absolutely. The writer, the expansion and the doctor are all
// told the same thing and dashes still arrive: proof run 83 on 15 Sep 2026
// came out of the doctor with eight. This pass finds every sentence that
// carries one and asks the model to restructure those sentences only. The
// apply node after it refuses any rewrite that still carries a dash, drops a
// number, or does not match the source text verbatim, so nothing here can
// change a fact silently. It never swaps a dash for a comma: Tee's rule is
// restructure the sentence, never swap the punctuation.
//
// Proof run 85 cleared the gate and left fragments behind ("As a binary
// switch."), so the prompt now carries two worked examples and the apply node
// refuses any rewrite that produces a sentence under five words.
const d = $json;
const ctx = $('Show Context: Script').first().json;
const DASH = /[—–]/;
const items = [];
for (const field of ['title', 'description', 'script']) {
  const raw = String(d[field] || '');
  const parts = raw.match(/[^.!?]+[.!?]+|[^.!?]+$/g) || [];
  for (const p of parts) {
    const s = p.trim();
    if (s && DASH.test(s) && !items.some(x => x.original === s)) items.push({ field, original: s });
  }
}
if (!items.length) return [{ json: { ...d, needsDashRepair: false, dashSentences: [] } }];

const budget = $('Token Budget: Script').first().json.body || {};
const system = [
  'You are the copy editor for ' + String(ctx.channel || 'The Quiet Operator') + '. You fix one thing only: sentences that carry an em dash or an en dash.',
  'Rewrite each sentence so it carries neither and still reads as complete, spoken prose. Every sentence you return must be a full sentence with a subject and a verb. Never leave a fragment such as "As a binary switch." or "Short, reusable AI functions." standing on its own.',
  'Ways to do it: fold the aside into the clause with the word that, which or such as; move the aside to the front or the end as its own full sentence; write the connecting word out. Never swap the dash for a comma, a semicolon, a colon or parentheses.',
  'Example. Given: We treat the headline – "AI replaces jobs" – as a switch. Return: We treat the headline that says "AI replaces jobs" as a switch.',
  'Example. Given: Teams publish micro-services – short, reusable AI functions – that others buy. Return: Teams publish micro-services, meaning short, reusable AI functions, that others buy. Or: Teams publish short, reusable AI functions as micro-services that others buy.',
  'A range written with a dash between two numbers is written with the word to, so 2019 to 2022.',
  'Keep every number, every name, every quoted phrase and every fact exactly as written. Change nothing outside the dash and the words needed to carry the clause.',
  'Never use an em dash, an en dash, or a hyphen standing in for either, anywhere in your output.'
].join('\n');
const user = [
  'Return only a JSON object in this shape: {"repairs": [{"original": "...", "rewritten": "..."}]}. One entry per numbered sentence below, in order, with original copied exactly as given.',
  '',
  ...items.map((it, i) => (i + 1) + '. ' + it.original)
].join('\n');
const repairBody = {
  model: budget.model || 'gpt-oss-120b',
  messages: [{ role: 'system', content: system }, { role: 'user', content: user }],
  max_completion_tokens: 6000,
  reasoning_effort: 'medium',
  response_format: { type: 'json_object' }
};
return [{ json: { ...d, needsDashRepair: true, dashSentences: items, repairBody } }];

// Parse Doctor Verdict (rebuilt 15 Sep 2026 as the dash repair apply step). It
// carries the node name that Originality Scan and DT Shim: Prior REST read, so
// whatever leaves here is the text every later node measures and saves. The
// doctor's own parser is now Parse Doctor Output, one node upstream.
//
// Every rewrite is verified before it is applied: it must carry no dash, it
// must keep the exact sequence of numbers the original carried, and the
// original must be found verbatim in the field it came from. A rewrite that
// fails any of those is skipped and named in last_feedback, and the gate then
// holds the script on the dashes that remain. Nothing here invents.
// Run 85 (15 Sep 2026) added the fragment check: a rewrite that leaves any
// sentence under five words is refused, because the first pass split at the
// dash and left "As a binary switch." standing alone.
const src = $('Dash Repair: Needs?').first().json;
const { repairBody, needsDashRepair, dashSentences, ...base } = src;
const stamp = new Date().toISOString();
if (!needsDashRepair) return [{ json: { ...base, dashRepair: 'not needed, no dashes after the doctor' } }];

const fail = (reason) => [{ json: {
  ...base,
  dashRepair: 'failed, text kept as the doctor left it: ' + reason,
  lastFeedback: String(base.lastFeedback || '') + '\n\nDASH REPAIR at ' + stamp + ' did not apply: ' + reason
} }];

const out = $json || {};
if (out.stop_reason === 'max_tokens' || out.choices?.[0]?.finish_reason === 'length') return fail('the response was truncated at the token ceiling');
let text = out.choices?.[0]?.message ? String(out.choices[0].message.content ?? '') : '';
if (!text.trim()) return fail('no text in the response');
text = text.replace(/```json/gi, '```');
const s0 = text.indexOf('{'), e0 = text.lastIndexOf('}');
if (s0 === -1 || e0 === -1) return fail('the response was not a JSON object');
let parsed;
try { parsed = JSON.parse(text.slice(s0, e0 + 1)); } catch (e) { return fail('the JSON did not parse: ' + e.message); }
const repairs = Array.isArray(parsed.repairs) ? parsed.repairs : [];
if (!repairs.length) return fail('the response carried no repairs');

const hasDash = (s) => /[—–]/.test(String(s));
const numbers = (s) => (String(s).match(/\d+(?:[.,]\d+)*/g) || []).join('|');
const fields = { title: String(base.title || ''), description: String(base.description || ''), script: String(base.script || '') };
const applied = [];
const skipped = [];
for (const r of repairs) {
  const original = String(r.original || '');
  const rewritten = String(r.rewritten || '').trim();
  const tag = original.slice(0, 70);
  if (!original || !rewritten) { skipped.push('empty pair'); continue; }
  if (hasDash(rewritten)) { skipped.push('rewrite still carries a dash: ' + tag); continue; }
  if (numbers(original) !== numbers(rewritten)) { skipped.push('rewrite changed a number: ' + tag); continue; }
  const shortSentence = (rewritten.match(/[^.!?]+[.!?]+|[^.!?]+$/g) || []).map(s => s.trim()).filter(Boolean).find(s => s.split(/\s+/).filter(Boolean).length < 5);
  if (shortSentence) { skipped.push('rewrite left a fragment ("' + shortSentence + '"): ' + tag); continue; }
  const known = (dashSentences || []).find(x => x.original === original);
  const field = known ? known.field : ['title', 'description', 'script'].find(f => fields[f].includes(original));
  if (!field || !fields[field].includes(original)) { skipped.push('original not found verbatim: ' + tag); continue; }
  fields[field] = fields[field].replace(original, rewritten);
  applied.push(field);
}
const remaining = ['title', 'description', 'script'].reduce((n, f) => n + (fields[f].match(/[—–]/g) || []).length, 0);
const note = [
  'DASH REPAIR at ' + stamp + ': ' + applied.length + ' sentence(s) restructured, ' + skipped.length + ' skipped, ' + remaining + ' dash(es) remain.',
  ...skipped.map(x => '  - ' + x)
].join('\n');
return [{ json: {
  ...base,
  title: fields.title,
  description: fields.description,
  script: fields.script,
  dashRepair: note,
  lastFeedback: String(base.lastFeedback || '') + '\n\n' + note
} }];

// DEVON Recall: Merge (added 15 Sep 2026). Ruled by Tee on an inline card:
// the writer is grounded by retrieval from his own record plus capture of his
// edits. This node folds two things onto the idea row before Build Script
// Prompt reads it: the devon-soul recall for this topic, and the newest
// exemplars of how Tee rewrote earlier machine drafts. Both are optional. A
// recall that fails (probe execution 86 on 15 Sep 2026 returned 401 because
// the stored credential does not match the service) is named in
// devonRecallNote and the script is still written; nothing here blocks.
const row = $('One Idea at a Time').first().json;
let recallText = '';
let recallNote = '';
try {
  const res = $('DEVON Recall: Ask').first().json || {};
  const code = Number(res.statusCode);
  let body = res.body;
  if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = null; } }
  if (code === 200 && body && Array.isArray(body.records)) {
    const recs = body.records.filter(r => r && String(r.text || '').trim()).slice(0, 7);
    recallText = recs.map(r => '- [' + String(r.source || 'soul') + ', score ' + (Number(r.score) || 0).toFixed(2) + '] ' + String(r.text).replace(/\s+/g, ' ').trim().slice(0, 600)).join('\n');
    recallNote = 'DEVON recall: ' + recs.length + ' record(s), ' + (body.tee_count ?? '?') + ' from Tee and ' + (body.devon_count ?? '?') + ' from DEVON' + (Array.isArray(body.errors) && body.errors.length ? '; partial: ' + body.errors.join('; ') : '');
  } else {
    const detail = body && body.detail ? String(body.detail) : (res.error ? String(res.error.message || res.error) : '');
    recallNote = 'DEVON recall unavailable (HTTP ' + (code || 'none') + (detail ? ', ' + detail.slice(0, 120) : '') + '); the script was written without it';
  }
} catch (e) {
  recallNote = 'DEVON recall did not run: ' + e.message;
}
const exemplars = $input.all().map(i => i.json || {}).filter(j => String(j.tee_script || '').trim());
const squeeze = (s, n) => String(s || '').replace(/\s+/g, ' ').trim().slice(0, n);
const exemplarText = exemplars.map((j, i) => [
  'Exemplar ' + (i + 1) + ' (' + String(j.topic || 'untitled') + ', captured ' + String(j.captured_at || '').slice(0, 10) + ', ' + (j.machine_words || '?') + ' machine words to ' + (j.tee_words || '?') + ' after Tee):',
  'MACHINE DRAFT OPENED: ' + squeeze(j.machine_script, 400),
  'TEE REWROTE IT AS: ' + squeeze(j.tee_script, 900)
].join('\n')).join('\n\n');
return [{ json: { ...row, devonRecall: recallText, devonRecallNote: recallNote, devonExemplars: exemplarText, devonExemplarCount: exemplars.length } }];

// Script Edits: Diff (added 15 Sep 2026). Edit capture, ruled by Tee on an
// inline card. Save Script writes the machine text to script_machine as well
// as script. By the time a row is promoted, script is whatever Tee left in it.
// A difference is a hand edit, and that pair is the writer's training signal:
// it lands in script_exemplars and DEVON Recall: Merge feeds the newest three
// back into the prompt. Identical text is not an exemplar and writes nothing.
const words = s => String(s).split(/\s+/).filter(Boolean).length;
const out = [];
for (const it of $input.all()) {
  const j = it.json || {};
  const machine = String(j.script_machine || '').trim();
  const now = String(j.script || '').trim();
  if (!machine || !now || machine === now) continue;
  out.push({ json: {
    source_row_id: Number(j.id),
    show: String(j.show || ''),
    topic: String(j.topic || ''),
    machine_script: machine,
    tee_script: now,
    machine_words: words(machine),
    tee_words: words(now),
    captured_at: new Date().toISOString(),
    note: 'captured at Promote from row ' + j.id + ' while its status was Scripted'
  } });
}
return out;

// Script: Still Short? (added 15 Sep 2026). Ruled by Tee on an inline card after
// proof run 104: the first expansion took an 859 word draft to 1184 and the
// doctor trimmed it to 1144, under the 1200 floor. When the expanded draft is
// still under EXPAND_BELOW this node prepares one more expansion, the second and
// last, from the current text. A draft at or over the floor goes straight to the
// doctor. The system prompt and the brief are reused verbatim from the first
// pass, as the first expansion does.
const EXPAND_BELOW = 1200;   // the gate's WORD_FLOOR; keep the two equal
const TARGET_LOW = 1800;
const TARGET_HIGH = 2200;

const d = $json;
const script = String(d.script || '');
const words = script.split(/\s+/).filter(Boolean).length;
if (words >= EXPAND_BELOW) {
  return [{ json: { ...d, needsExpansion2: false } }];
}

const budget = $('Token Budget: Script').first().json.body || {};
const msgs = Array.isArray(budget.messages) ? budget.messages : [];
const system = msgs.filter(m => m.role === 'system').map(m => String(m.content || '')).join('\n\n');
const brief = msgs.filter(m => m.role === 'user').map(m => String(m.content || '')).join('\n\n');
const draft = { title: d.title || '', script, description: d.description || '', tags: d.tags || '', broll: d.broll || '' };

const user = [
  'The draft below is still ' + words + ' words after one expansion. The brief requires at least ' + EXPAND_BELOW + ' words and the target is ' + TARGET_LOW + ' to ' + TARGET_HIGH + '. This is the last expansion, so land inside the target.',
  'Expand it to between ' + TARGET_LOW + ' and ' + TARGET_HIGH + ' words. Rules for the expansion:',
  '- Keep the hook, the first two sentences, exactly as written.',
  ...(d.learningObjective ? ['- Keep the learning objective word for word and inside the first 70 words, and add nothing before it. It reads: ' + d.learningObjective] : []),
  ...(Array.isArray(d.checklist) && d.checklist.length ? ['- Keep the checklist steps word for word and in order, with none added or removed. Lengthen around them, not inside them. They read: ' + d.checklist.map((s, i) => (i + 1) + '. ' + s).join(' ')] : []),
  '- Keep every section and its order. Lengthen each one with a concrete example, a mechanism the viewer can follow, or a number the viewer can check. Where the draft has no verifiable number, add a worked example instead of inventing a statistic.',
  '- Add at least ' + Math.max(400, TARGET_LOW - words) + ' words of new material spread across the sections. Count before you answer.',
  '- Keep the title, description, tags and broll unchanged unless the expansion makes one of them wrong.',
  '- Never use an em dash or an en dash anywhere. Use a comma, a full stop or the word to.',
  '- Do not summarise, compress or drop anything that is in the draft.',
  'Return only a JSON object in exactly this shape: {"title": "...", "script": "...", "description": "...", "tags": "...", "broll": ["...", "..."]}.',
  '',
  'THE ORIGINAL BRIEF:',
  brief,
  '',
  'THE DRAFT TO EXPAND (JSON):',
  JSON.stringify(draft)
].join('\n');

const expandBody = {
  model: budget.model || 'gpt-oss-120b',
  messages: [ ...(system ? [{ role: 'system', content: system }] : []), { role: 'user', content: user } ],
  max_completion_tokens: budget.max_completion_tokens || 10000,
  reasoning_effort: 'medium',
  response_format: { type: 'json_object' }
};

return [{ json: { ...d, stillShortWords: words, needsExpansion2: true, expandBody } }];

// Parse Expanded Script 2 (added 15 Sep 2026). Same contract as Parse Expanded
// Script: returns the Parse Script JSON shape so Build Doctor Prompt needs no
// rewiring. If the second expansion cannot be used, the text that entered this
// pass goes on unchanged with the reason appended to the expansion note. A
// failed expansion never costs the draft.
const prev = $('Script: Still Short?').first().json;
const { expandBody, needsExpansion2, stillShortWords, ...base } = prev;
const before = Number(stillShortWords) || 0;
const note = String(base.expansion || '');

function keepDraft(reason) {
  return [{ json: { ...base, expansion: note + '; second pass failed, kept at ' + before + ' words: ' + reason } }];
}

const out = $json || {};
if (out.stop_reason === 'max_tokens' || out.choices?.[0]?.finish_reason === 'length') return keepDraft('truncated at the token ceiling');
let text = out.choices?.[0]?.message ? String(out.choices[0].message.content ?? '') : String(out.content?.[0]?.text ?? '');
if (!text.trim()) return keepDraft('no text returned');

text = text.replace(/```json/gi, '```');
const start = text.indexOf('{');
const end = text.lastIndexOf('}');
if (start === -1 || end === -1) return keepDraft('not a JSON object');
let parsed;
try { parsed = JSON.parse(text.slice(start, end + 1)); } catch (e) { return keepDraft('JSON did not parse: ' + e.message); }

const script = String(parsed.script || '');
const words = script.split(/\s+/).filter(Boolean).length;
if (words <= before) return keepDraft('came back at ' + words + ' words, no longer');

return [{ json: {
  ...base,
  title: String(parsed.title || base.title || ''),
  script,
  description: String(parsed.description || base.description || ''),
  tags: Array.isArray(parsed.tags) ? parsed.tags.join(', ') : String(parsed.tags ?? base.tags ?? ''),
  broll: Array.isArray(parsed.broll) ? parsed.broll.map(s => String(s).trim()).filter(Boolean).join(', ') : String(parsed.broll || base.broll || ''),
  expansion: note + ', then a second pass to ' + words + ' words',
  expandedWords: words
} }];

// Paddy Galloway's order, applied to V5: the package is decided before the
// episode exists rather than assembled from it afterwards. The atomizer further
// down the publish lane still does the repurposing work off the finished
// script. This node does only the job that has to happen first, which is to
// give the idea ten titles and five thumbnail angles, ranked into three
// packages, so Tee can pick one and the script can be written to pay off a
// promise that is already on the table. Ruled 16 Sep 2026: the model ranks,
// Tee picks, the package locks.
const ctx = $('Show Context: Script').first().json;
const row = $json;
const f = row.fields || row;

const recordId = row.id != null ? row.id : f.id;
const topic = String(f.Topic || row.topic || '');
const idea = String(f.Idea || row.idea || '');
const show = String(f.Show || row.show || '');
if (!topic.trim() && !idea.trim()) {
  return [{ json: { recordId, packageOk: false, packageError: 'Row has neither Topic nor Idea, so there is nothing to package.' } }];
}

const isNCO = ctx.show === 'NCO';
const cap = isNCO ? 4 : 5;

const system = [
  isNCO
    ? 'You write packaging for NCO FORGE. Leaders are not born, they are forged. Position: where doctrine ends and leadership begins. Voice: direct, practical, respectful of service.'
    : 'You write packaging for THE QUIET OPERATOR. Leverage for the people the AI economy is quietly repricing. Voice: calm, analytical, unhurried. Receipts over promises.',
  '',
  'The episode does not exist yet. You are packaging the idea, and what you return decides what the',
  'episode has to deliver. Do not write the episode.',
  '',
  'TITLES. Return exactly 10, two each across five families: story, question, outcome, contrarian, search.',
  'The fewest words that still carry the promise. Universal language, no insider shorthand, no stacked colons.',
  'Readable at a glance on a phone, under 60 characters. It has to complement a thumbnail, not repeat it.',
  'Do not rank them and do not mark a favourite inside the list.',
  '',
  'THUMBNAIL CONCEPTS. Return exactly 5, one per psychological angle: betrayal or cost, regret or admission,',
  'identity, curiosity, consequence. Five different angles, never five wordings of one idea.',
  'text is at most ' + cap + ' words, upper case, describing human tension rather than generic negativity.',
  'The text must say something the title does not. If a concept only restates a title, replace it.',
  'visual is one concrete subject a stock library would actually have: a person, an object, a place.',
  'Never an abstract noun, never a diagram, never text on a screen.',
  '',
  'PROMISE. For every title, one line naming what the episode must deliver for that title to be honest.',
  'A title the episode cannot pay off is the fastest way to lose an audience, so write the bill next to the promise.',
  '',
  'RANKING. Then rank the three strongest packages, best first. A package is one title paired with one',
  'thumbnail concept, chosen together so the thumbnail text says something the title does not and the two',
  'make one promise. Three different titles. One plain sentence each on why a viewer clicks it. The person',
  'who runs this channel picks one of the three by hand, so the ranking is advice, not a decision.',
  '',
  'ABSOLUTE RULES',
  'No em dashes. No en dashes. Ever. Use a comma, colon, semicolon or full stop.',
  'No invented statistics, numbers, studies or quotes.',
  'No hype vocabulary: game changer, secret, hack, unlock, supercharge, 10x, masterclass, this changes everything.',
  'No empty intensifiers: truly, deeply, incredibly, absolutely, profound, transformative.',
  'No engagement bait. No all upper case in the titles themselves.',
  '',
  'Return ONLY valid JSON, no fences, exactly these keys:',
  '{"titles":[{"family":"story|question|outcome|contrarian|search","title":"","promise":""}],',
  '"thumbnail_concepts":[{"angle":"betrayal|regret|identity|curiosity|consequence","text":"","visual":""}],',
  '"ranked":[{"title_index":0,"concept_index":0,"why":"one plain sentence"}]}',
  '',
  'Counts are exact: titles 10, thumbnail_concepts 5, ranked 3. Indexes are zero based and point into the two lists above.'
].join('\n');

const user = [
  'Channel: ' + ctx.channel,
  'Show: ' + (show || 'unassigned'),
  'Topic: ' + topic,
  idea ? 'Editorial direction: ' + idea : ''
].filter(Boolean).join('\n');

return [{ json: { recordId, packageOk: true, body: {
  model: 'claude-sonnet-5', max_tokens: 4000, system, messages: [{ role: 'user', content: user }]
} } }];

// Output ceiling for the first-pass packaging call. Ten titles with a promise
// line each and five thumbnail concepts is the same volume of structured output
// the post-render packaging call produces, and that one is given 24000, so this
// one gets 24000. gpt-oss-120b is a reasoning model and reasoning tokens are
// charged against this ceiling, so an estimate based on the visible answer
// length underfunds it. Same Anthropic-shape to Cerebras conversion the other
// model calls use, kept local so raising one ceiling never silently raises
// another.
const MAX_TOKENS = 24000;
const j = { ...$json };
if (!j.body) return [{ json: j }];
const SUFFIX = '\n\nOutput rules that override anything above: never use an em dash or an en dash anywhere in any field, use a comma, a full stop or the word to instead.';
const b = j.body;
const sys = (typeof b.system === 'string' && b.system) ? [{ role: 'system', content: b.system + SUFFIX }] : [];
j.body = {
  model: 'gpt-oss-120b',
  messages: [...sys, ...(Array.isArray(b.messages) ? b.messages : [])],
  max_completion_tokens: MAX_TOKENS,
  reasoning_effort: 'medium',
  response_format: { type: 'json_object' }
};
return [{ json: j }];

// Two failure paths, told apart on purpose. A model that answered badly is a
// packaging failure: the row goes to Error carrying the reason, because retrying
// does not fix a bad answer. A model that never answered at all, an unfunded key,
// a timeout, a dropped connection, a reply cut off at the token ceiling, is an
// infrastructure failure: this node throws, the run stops loudly and the row is
// left at Idea for the next pass. Condemning the backlog because the billing
// lapsed or the ceiling was too low is what that prevents.
//
// What this node produces changed on 22 Sep 2026 to match the ruling of 16 Sep:
// the model ranks, Tee picks, the package locks. It no longer chooses a title.
// It validates the ten titles and five concepts, builds the three ranked
// packages the model proposed (title plus thumbnail text plus subject, each
// pairing checked so the thumbnail says something the title does not), and
// hands them to Package: Write Options. Nothing here writes video_title or
// package_locked. Tee does, by setting package_locked to 1, 2 or 3.
const src = $('Package: Build Prompt').first().json;
const recordId = src.recordId;
const ctx = $('Show Context: Script').first().json;
const cap = ctx.show === 'NCO' ? 4 : 5;
const s = v => String(v == null ? '' : v).trim();

function fail(reason) {
  return [{ json: { recordId, packageOk: false, packageError: String(reason).slice(0, 900) } }];
}
function halt(reason) {
  throw new Error('PACKAGING HELD, not failed. ' + String(reason).slice(0, 500) +
    ' Row ' + recordId + ' was left at Idea and nothing was written, so it packages normally once the model call works again.');
}
if (src.packageOk === false) return fail(src.packageError);

const r = $json || {};
if (r.error) {
  // Only an account or transport failure stops the run: unfunded (402), bad key
  // (401, 403), rate limit (429), provider outage (5xx), or no HTTP status at
  // all (timeout, dropped connection). Any other 4xx is this request being
  // rejected, which a retry tomorrow will not change, so that row goes to Error
  // with the reason instead of blocking every row behind it every day.
  const msg = String(r.error.message || JSON.stringify(r.error));
  const code = Number((msg.match(/^\s*(\d{3})\b/) || [])[1] || r.error.status || r.error.statusCode || 0);
  const accountOrTransport = !code || code === 401 || code === 402 || code === 403 || code === 408 || code === 429 || code >= 500;
  if (accountOrTransport) return halt('The packaging model call did not succeed: ' + msg.slice(0, 300));
  return fail('The packaging model rejected this request with HTTP ' + code + ': ' + msg.slice(0, 300));
}

let text = '';
try {
  text = String(r.choices[0].message.content || '');
} catch (e) {
  return halt('No choices[0].message.content in the model response, so the model never answered. Top level keys seen: ' + Object.keys(r).join(', '));
}
if (!text.trim()) return halt('The model returned an empty message.');

let finish = '';
try { finish = String(r.choices[0].finish_reason || ''); } catch (e) { /* shape already checked above */ }
if (finish === 'length') {
  return halt('The model hit the output ceiling and the answer was cut off mid sentence, so the package is incomplete rather than bad. Raise MAX_TOKENS in Token Budget: Package. Characters returned: ' + text.length + '.');
}

let p;
try {
  p = JSON.parse(text.replace(/^```(?:json)?/i, '').replace(/```$/, '').trim());
} catch (e) {
  return fail('Model output was not valid JSON: ' + e.message + ' | first 200 chars: ' + text.slice(0, 200));
}

const DASH = /[—–]/;
const titles = (Array.isArray(p.titles) ? p.titles : []).filter(t => t && s(t.title));
const concepts = (Array.isArray(p.thumbnail_concepts) ? p.thumbnail_concepts : []).filter(c => c && s(c.text) && s(c.visual));
if (titles.length < 5) return fail('Only ' + titles.length + ' usable titles returned. The brief asks for 10 and the floor is 5.');
if (!concepts.length) return fail('No usable thumbnail concepts returned.');

// Thumbnail text obeys the brand word cap and loses dashes and punctuation, so a
// picked headline can go straight to the renderer.
const headWords = c => s(c && c.text)
  .replace(DASH, ' ')
  .replace(/[^A-Za-z0-9' ]/g, ' ')
  .replace(/\s+/g, ' ')
  .trim()
  .toUpperCase()
  .split(' ').filter(Boolean);
const toHeadline = c => headWords(c).slice(0, cap).join(' ');
const toSubject = c => s(c && c.visual).replace(DASH, ' ').split(',')[0].trim();

// Ruled 16 Sep 2026: thumbnail text must say something the title does not.
// Word overlap, not substring, so "LIED FOR YEARS" against "She Lied To Me For
// Years" counts as a repeat and "HE LIED" against "she lied" does not.
const words = str => new Set(String(str).toLowerCase().replace(/[^a-z0-9 ]/g, ' ').split(/\s+/).filter(Boolean));
const repeatsTitle = (c, title) => {
  const h = words(toHeadline(c)); const t = words(title);
  if (!h.size) return true;
  let shared = 0; h.forEach(w => { if (t.has(w)) shared++; });
  return shared / h.size >= 0.6;
};

// A title with a dash is never used. The rule is restructure the sentence,
// never swap the punctuation, and a string replace cannot restructure.
const inRange = (n, len) => Number.isInteger(n) && n >= 0 && n < len;
const usableTitle = i => inRange(i, titles.length) && !DASH.test(s(titles[i].title));

// Build the ranked packages from the model's own ranking, then fill to three
// from the remaining titles in order, so Tee always sees three choices.
const ranked = [];
const usedTitles = new Set();
const warningsAll = [];
function buildPackage(ti, ci, why) {
  if (!usableTitle(ti) || usedTitles.has(ti)) return null;
  const title = s(titles[ti].title);
  const order = [ci, ...concepts.map((c, i) => i).filter(i => i !== ci)].filter(i => inRange(i, concepts.length));
  let pick = order.find(i => !repeatsTitle(concepts[i], title));
  const warnings = [];
  if (pick === undefined) { pick = inRange(ci, concepts.length) ? ci : 0; warnings.push('Every thumbnail concept repeats this title. Swap the text before this one renders.'); }
  else if (pick !== ci && inRange(ci, concepts.length)) warnings.push('The model paired concept ' + ci + ' with this title but its text repeated the title, so concept ' + pick + ' is paired instead.');
  const c = concepts[pick];
  const headline = toHeadline(c); const subject = toSubject(c);
  if (headWords(c).length > cap) warnings.push('Thumbnail text "' + s(c.text) + '" runs past the ' + cap + ' word cap and was cut to "' + headline + '". Shorten it before this one renders.');
  if (!headline || !subject) return null;
  usedTitles.add(ti);
  return { rank: ranked.length + 1, title, headline, subject, promise: s(titles[ti].promise), why: s(why), family: s(titles[ti].family), angle: s(c.angle), title_index: ti, concept_index: pick, warnings };
}
const proposed = Array.isArray(p.ranked) ? p.ranked : [];
for (const e of proposed) {
  if (ranked.length >= 3 || !e) continue;
  const pkg = buildPackage(Number(e.title_index), Number(e.concept_index), e.why);
  if (pkg) ranked.push(pkg);
}
if (ranked.length < 3) warningsAll.push('The model ranked ' + ranked.length + ' usable package(s); the rest were filled from the remaining titles in order.');
for (let ti = 0; ti < titles.length && ranked.length < 3; ti++) {
  const pkg = buildPackage(ti, 0, 'filled in title order because the model ranked fewer than three usable packages');
  if (pkg) ranked.push(pkg);
}
if (!ranked.length) return fail('No usable package could be built: every title carries a dash or no concept produced a headline and subject.');

let executionId = '';
try { executionId = String($execution.id || ''); } catch (e) { executionId = ''; }
const proposedAt = new Date().toISOString();
const options = {
  how_to_pick: 'Set package_locked on this row to 1, 2 or 3 to lock that package. The next script pass writes the episode to pay off that title. To use your own title instead, write it into video_title and set package_locked to tee.',
  ranked,
  warnings: warningsAll,
  titles: titles.map(t => ({ family: s(t.family), title: s(t.title), promise: s(t.promise), dash: DASH.test(s(t.title)) })),
  thumbnail_concepts: concepts.map(c => ({ angle: s(c.angle), text: s(c.text), visual: s(c.visual) })),
  model: 'gpt-oss-120b',
  execution: executionId,
  proposed_at: proposedAt
};

return [{ json: {
  recordId,
  packageOk: true,
  packageOptions: JSON.stringify(options, null, 2),
  proposedAt,
  rankedCount: ranked.length,
  titleCount: titles.length,
  conceptCount: concepts.length,
  topTitle: ranked[0].title,
  topHeadline: ranked[0].headline
} }];

// The single answer to "what package is this episode committed to". Reached
// only for a row Package: Plan Batch classed as locked, which means Tee set
// package_locked: either 1, 2 or 3 to take a ranked entry from package_options,
// or any other mark with the title he wants already in video_title. The model
// never writes package_locked. Ruled 16 Sep 2026: the model ranks, Tee picks,
// the package locks. Everything downstream reads this node rather than the row
// so the resolved title, headline and subject travel together.
//
// The idea row is spread back into the output on purpose. This node sits in the
// data path directly ahead of DEVON Recall: Ask, whose query is built from
// $json.Topic and $json.Idea.
const row = $('One Idea at a Time').first().json;
const f = row.fields || row;
const s = v => String(v == null ? '' : v).trim();
const mark = s(row.package_locked || f['Package Locked']);
if (!mark) throw new Error('Package: Context was reached for row ' + row.id + ' with no package_locked. Only locked rows are routed here, so the wiring changed. Nothing was written.');

let videoTitle = '', thumbnailHeadline = '', primarySubject = '', promise = '', why = '', source = '';
if (/^[1-3]$/.test(mark)) {
  let opts = null;
  try { opts = JSON.parse(s(row.package_options || f['Package Options'])); } catch (e) { opts = null; }
  const ranked = opts && Array.isArray(opts.ranked) ? opts.ranked : [];
  const p = ranked[Number(mark) - 1];
  if (!p || !s(p.title)) throw new Error('PACKAGE PICK UNRESOLVED on row ' + row.id + ': package_locked is ' + mark + ' but package_options has no ranked entry ' + mark + '. Nothing was written. Plan Batch should have left this row out.');
  videoTitle = s(p.title); thumbnailHeadline = s(p.headline); primarySubject = s(p.subject);
  promise = s(p.promise); why = s(p.why);
  source = 'Tee picked ranked option ' + mark;
} else {
  videoTitle = s(f['Video Title'] || row.video_title);
  thumbnailHeadline = s(f['Thumbnail Headline'] || row.thumbnail_headline);
  primarySubject = s(f['Primary Subject'] || row.primary_subject);
  if (!videoTitle) throw new Error('PACKAGE PICK UNRESOLVED on row ' + row.id + ': package_locked is "' + mark + '" but video_title is empty. Nothing was written.');
  source = 'Tee supplied the title, package_locked = "' + mark + '"';
}
if (/[—–]/.test(videoTitle)) throw new Error('The locked title on row ' + row.id + ' carries an em or en dash: "' + videoTitle + '". Restructure it in video_title, never swap the punctuation. Nothing was written.');

return [{ json: { ...row,
  packageLocked: true,
  videoTitle, thumbnailHeadline, primarySubject, promise, why,
  lockedAt: mark,
  overlapsTitle: false,
  source
} }];

// The package is already chosen, so the script writer's job changes: it is no
// longer proposing a title, it is paying one off. Appended the same way the
// series layer is appended, so the brand prompt upstream stays untouched.
const pkg = $('Package: Context').first().json;
const body = $json.body || $json.claudeBody;
if (!body || !pkg || !pkg.packageLocked || !pkg.videoTitle) return [$input.item];

const lines = [
  '',
  '=== THE PACKAGE IS ALREADY CHOSEN ===',
  'This episode was packaged before it was written. The title and thumbnail below are locked, and the',
  'audience will have seen both before a single second of the episode plays.',
  '',
  'TITLE: ' + pkg.videoTitle,
  'THUMBNAIL TEXT: ' + (pkg.thumbnailHeadline || '(none)'),
  'THUMBNAIL SUBJECT: ' + (pkg.primarySubject || '(none)'),
  'WHAT THE TITLE PROMISES: ' + (pkg.promise || '(not recorded; read the promise off the title itself)'),
  (pkg.why ? 'WHY THIS PACKAGE WAS PICKED: ' + pkg.why : ''),
  '',
  'The episode has to pay that promise in full. A title the episode does not pay off loses the audience.',
  'Return this exact title in the title field, character for character. Do not improve it, shorten it,',
  'repunctuate it or offer an alternative. If you believe it is wrong, write the episode anyway and say',
  'so in one line at the end of the description, where a human reads it before anything ships.',
  '',
  'The opening has to confirm the promise the viewer clicked on. Inside the first thirty seconds the',
  'viewer must be able to tell this is the episode the title and thumbnail advertised. Do not restate',
  'the title as your first line. Deliver what it promised.',
  '',
  'The primary keyword guidance above now applies to the description only. The title is no longer yours.'
].join('\n');

body.system = String(body.system || '') + '\n' + lines;
const msgs = Array.isArray(body.messages) ? body.messages : [];
if (msgs.length) {
  msgs[msgs.length - 1].content = String(msgs[msgs.length - 1].content || '') +
    '\nLocked title: ' + pkg.videoTitle +
    '\nLocked thumbnail text: ' + (pkg.thumbnailHeadline || '');
}
return [{ json: { ...$json, body } }];

// Package: Plan Batch. Decides what this pass does with the Idea rows, in the
// order ruled 16 Sep 2026: the model ranks, Tee picks, the package locks, and
// only then is the script written. Three kinds of Idea row arrive here.
//   locked:  package_locked is set. Either Tee's pick (1, 2 or 3, naming an
//            entry in package_options.ranked) or any other mark with his own
//            title already in video_title. These go first and are scripted,
//            up to scriptLimit.
//   pending: package_options is filled and package_locked is empty. Tee has
//            not picked. Nothing to do, so they are left out of this pass and
//            never block the rows behind them.
//   fresh:   neither. These are packaged (options written, no lock), up to
//            packageLimit.
// A locked row whose pick cannot be resolved is left out with a note rather
// than thrown on, because one mistyped cell must not end the day for both
// brands. Package: Context is strict about the same thing, so a row that gets
// there always resolves.
const ctx = $('Show Context: Script').first().json;
const scriptLimit = Number(ctx.scriptLimit) > 0 ? Number(ctx.scriptLimit) : 2;
const packageLimit = Number(ctx.packageLimit) > 0 ? Number(ctx.packageLimit) : 3;
const s = v => String(v == null ? '' : v).trim();

// Every reason Package: Context would refuse a row is checked here first, so a
// refused row is left out of the pass with its reason in the plan note instead
// of throwing and ending the day for both brands.
const DASH = /[—–]/;
function pickResolves(j) {
  const f = j.fields || j;
  const mark = s(j.package_locked);
  if (/^[1-3]$/.test(mark)) {
    let opts = null;
    try { opts = JSON.parse(s(j.package_options)); } catch (e) { return 'package_locked is ' + mark + ' but package_options is not readable JSON'; }
    const ranked = opts && Array.isArray(opts.ranked) ? opts.ranked : [];
    const p = ranked[Number(mark) - 1];
    if (!p || !s(p.title)) return 'package_locked is ' + mark + ' but package_options has no ranked entry ' + mark;
    if (DASH.test(s(p.title))) return 'ranked option ' + mark + ' carries an em or en dash in its title. Pick another option';
    return '';
  }
  // Any other mark means Tee wrote the package himself. It needs a title and a
  // thumbnail headline of its own, because deriving the headline from the title
  // is the one thing the 16 Sep ruling forbids. Half the TQO idea rows already
  // carry a seeded video_title, so a stray mark must not lock one by accident.
  const title = s(f['Video Title'] || j.video_title);
  const head = s(f['Thumbnail Headline'] || j.thumbnail_headline);
  if (!title) return 'package_locked is "' + mark + '" but video_title is empty. Use 1, 2 or 3 for a ranked option, or write the title you want into video_title and a headline into thumbnail_headline';
  if (!head) return 'package_locked is "' + mark + '" with your own title but thumbnail_headline is empty. Write the thumbnail text too, or use 1, 2 or 3 for a ranked option';
  if (DASH.test(title)) return 'package_locked is "' + mark + '" but video_title carries an em or en dash. Restructure the title, never swap the punctuation';
  return '';
}

const items = $input.all();
const locked = [], pending = [], fresh = [], unresolved = [];
for (const it of items) {
  const j = it.json || {};
  if (s(j.package_locked)) {
    const problem = pickResolves(j);
    if (problem) unresolved.push('row ' + j.id + ': ' + problem); else locked.push(it);
  } else if (s(j.package_options)) pending.push(it);
  else fresh.push(it);
}
const out = [...locked.slice(0, scriptLimit), ...fresh.slice(0, packageLimit)];
const note = 'plan: ' + items.length + ' idea rows in, ' + locked.length + ' locked (' + Math.min(locked.length, scriptLimit) + ' scripted this pass), '
  + pending.length + ' pending a pick, ' + fresh.length + ' fresh (' + Math.min(fresh.length, packageLimit) + ' packaged this pass)'
  + (unresolved.length ? '; left out, pick unresolved: ' + unresolved.join(' | ') : '');
return out.map(it => ({ json: { ...it.json, __plan: note } }));

// Ruled by Tee 2026-09-22: fix the code, leave the records already written.
//
// WHAT THIS PREVENTS. Both drop nodes carry onError continueRegularOutput, so a
// Drive failure arrives here as an ordinary item carrying json.error. The slot
// used to be marked Ready with a Posted At stamp and a note claiming the drop
// whatever Drive answered. A success response is a claim. The receipt is the
// file id Drive returns.
//
// On a failure the update carries the note ONLY in effect: Mark Handed Off
// writes status back as Pending (the only status this lane selects) and
// posted_at back to its prior value, so nothing claims a handoff that did not
// happen.
//
// 2026-09-23: the slot lives in n8n data table at_tqo_publishing, not Airtable,
// so this emits plain fields for a data table update instead of an Airtable
// PATCH body.
const plan = $('Repurpose: Plan Drops').item.json;
const r = $input.item.json || {};
const now = new Date().toISOString();
const platform = String(plan.platform || 'target');
const asset = String(plan.assetId || 'the asset');
const failed = Boolean(r.error) || !r.id;

if (!failed) {
  return { json: {
    dropped: true,
    slotId: plan.slotId,
    fileId: String(r.id),
    postedAt: now,
    priorPostedAt: plan.priorPostedAt,
    notes: 'Dropped ' + asset + ' in the Repurpose ' + platform + ' folder at ' + now
      + ' (Drive file ' + String(r.id) + '). Repurpose owns the post from here. If nothing appears, the workflow on their side is not pointed at this folder, or the destination is switched off.'
  } };
}

const e = r.error || {};
const why = String(e.message || e.description || r.message || 'Drive returned no file id')
  .replace(/\s+/g, ' ')
  .slice(0, 300);
return { json: {
  dropped: false,
  slotId: plan.slotId,
  fileId: '',
  postedAt: '',
  priorPostedAt: plan.priorPostedAt,
  notes: 'NOT DROPPED at ' + now + '. Google Drive refused: ' + why + '. Nothing reached the Repurpose ' + platform + ' folder, so ' + asset
    + ' is not there and Repurpose has nothing to post. Status and posted_at are deliberately left unchanged rather than claiming a handoff that did not happen.'
} };

// Plan Presenter Segments - v1, wired 2026-09-30 (Quality Law rev2, presenter-led).
//
// Ruled by Tee: all lanes are presenter-led. Terrance Veal's avatar (HeyGen/
// Runway clips, ElevenLabs clone voice baked in) delivers on camera; b-roll is
// the bridge. This node decides WHICH sentence spans of the episode are
// PRESENTED (the avatar on camera) and which are B-ROLL, then emits an ordered
// timeline that Build Movie v9 consumes.
//
// Presented spans by law: the HOOK, the CHECKLIST, the CLOSE, and key receipt
// moments. A script that reads as pure voiceover fails quality law check 12.
//
// Duration estimate: 150 WPM, same constant Plan B-Roll Segments uses, so the
// two planners agree on how long the narration takes.
const ROW = $('Process Each Video');
const fields = ROW.item.json.fields || {};
const script = String(fields['Script'] || '');
if (!script.trim()) throw new Error('Plan Presenter Segments: script empty for row ' + (fields.id || '?'));

const WPM = 150;
const secsFor = (txt) => (String(txt).trim().split(/\s+/).filter(Boolean).length / WPM) * 60;
const sentences = script.replace(/\s+/g, ' ').match(/[^.!?]+[.!?]+|[^.!?]+$/g) || [script];

const stepRx = /^(step one|step two|step three|step four|step five|first,|second,|third,|next,|then,|finally,)/i;
const receiptRx = /\d/;

const spans = [];
for (let i = 0; i < sentences.length; i++) {
  const s = sentences[i].trim();
  let kind = 'broll';
  if (i <= 1) kind = 'presenter';
  else if (i >= sentences.length - 2) kind = 'presenter';
  else if (stepRx.test(s)) kind = 'presenter';
  else if (receiptRx.test(s) && s.length > 60) kind = 'presenter';
  spans.push({ index: i, text: s, kind });
}

const timeline = [];
let cursor = 0;
for (const s of spans) {
  const dur = Math.max(2, Math.round(secsFor(s.text) * 10) / 10);
  const last = timeline[timeline.length - 1];
  if (last && last.kind === s.kind) {
    last.text += ' ' + s.text;
    last.duration = Math.round((last.duration + dur) * 10) / 10;
  } else {
    timeline.push({ kind: s.kind, text: s.text, start: Math.round(cursor * 10) / 10, duration: dur });
  }
  cursor += dur;
}

const rowId = String(fields.id || ROW.item.json.id || 'unknown');
const shotList = timeline
  .map((t, i) => ({ ...t, segmentIndex: i }))
  .filter(t => t.kind === 'presenter')
  .map(t => ({
    segmentIndex: t.segmentIndex,
    file: 'presenter-' + rowId + '-' + t.segmentIndex + '.mp4',
    text: t.text,
    duration: t.duration,
  }));

const presentedSecs = timeline.filter(t => t.kind === 'presenter').reduce((a, t) => a + t.duration, 0);
const totalSecs = timeline.reduce((a, t) => a + t.duration, 0);

return { json: {
  rowId,
  timeline,
  shotList,
  presenterClipCount: shotList.length,
  presentedSecs: Math.round(presentedSecs),
  totalSecs: Math.round(totalSecs),
  presenterCoverage: totalSecs ? Math.round((presentedSecs / totalSecs) * 100) : 0,
} };

// Presenter: Write Shot List - v1, wired 2026-09-30 (presenter layer build).
// Persists the HeyGen/Runway shot list onto the row so the presenter batch has
// its manifest, and so Build Movie v9's refusal can name what is missing.
const plan = $('Plan Presenter Segments').item.json;
const row = $('Process Each Video').item.json;
const fields = row.fields || {};
const rowId = String(fields.id || row.id || plan.rowId);
const shotListText = plan.shotList.map(s =>
  '[' + s.segmentIndex + '] ' + s.duration + 's - ' + s.file + '\n  DELIVER: ' + s.text
).join('\n');
return { json: {
  rowId,
  timeline: plan.timeline,
  shotList: plan.shotList,
  shotListText,
  presenterClipCount: plan.presenterClipCount,
  presentedSecs: plan.presentedSecs,
  totalSecs: plan.totalSecs,
  presenterCoverage: plan.presenterCoverage
} };

// Presenter: Attach Clips - v3.1, 2026-10-05 (Claude chat session, Tee rulings 5 Oct 2026).
// v3.1 after critic pass: a clip must also carry voice_track_in_clip true (a
// silent clip keyed to an episode no longer passes), keys are trimmed, a clip
// with no drive_file_id is refused, the newest row wins a duplicate segment,
// and the row is read with .item like Write Shot List (proven in exec 1872).
//
// RULING: no lip-synced episode clip, no render. Library stock no longer stands
// in for a presenter segment. The six LIBRARY rows show Tee silent (window pose,
// desk nod, arms folded) or show hands only, and they were laid at the wrong
// timestamps, so a real episode shipped as voiceover with nobody told. That path
// is gone. A planned presenter segment with no clip throws, naming the segment.
//
// DATA TABLE KEYING: since the Airtable migration, row ids are per-table
// integers, so NCO row 46 and TQO row 46 are different episodes. Clips are
// matched on episode_row_id = '<brand>:<id>' (e.g. 'tqo:46', 'nco:26'), brand
// from Show Context: Render. A clip keyed with a bare id is never attached; the
// refusal names it so it can be rekeyed.
//
// v2 history: v1 matched episode_row_id === rowId only and library clips never
// matched (exec 1670). v2 added the library round-robin that v3 removes.
const ctx = $('Show Context: Render').first().json;
const brand = String(ctx.brand || '').toLowerCase();
const plan = $('Presenter: Write Shot List').first().json;
const rowId = String(plan.rowId);
const key = brand + ':' + rowId;
const row = $('Process Each Video').item.json;
const f = row.fields || row;
const rows = $('Presenter: Fetch Clips').all().map(i => i.json || {});
const timeline = Array.isArray(plan.timeline) ? plan.timeline : [];
const shots = Array.isArray(plan.shotList) ? plan.shotList : [];

if (!brand) throw new Error('PRESENTER REFUSAL - Show Context: Render carries no brand, so clips cannot be keyed. Nothing rendered.');

const keyOf = r => String(r.episode_row_id || '').trim().toLowerCase();
const mine = rows
  .filter(r => r.share_verified === true && r.voice_track_in_clip === true && String(r.drive_file_id || '').trim() && keyOf(r) === key)
  .sort((a, b) => Number(b.id || 0) - Number(a.id || 0));
const bare = rows.filter(r => keyOf(r) === rowId);
const unusable = rows.filter(r => keyOf(r) === key && !mine.includes(r));

const pres = [];
const missing = [];
for (const s of shots) {
  const seg = Number(s.segmentIndex);
  const c = mine.find(r => Number(r.segment_index) === seg);
  if (!c) {
    missing.push('segment ' + seg + ' (' + s.duration + 's): ' + String(s.text || '').slice(0, 80));
    continue;
  }
  // shotList.segmentIndex is the index into the full timeline, so the start
  // time is read straight off that entry.
  const t = timeline[seg] || {};
  pres.push({
    segmentIndex: seg,
    file: 'presenter-' + brand + '-' + rowId + '-' + seg + '.mp4',
    publicUrl: 'https://drive.usercontent.google.com/download?id=' + c.drive_file_id + '&export=download&confirm=t',
    duration: Number(c.duration_seconds) > 0 ? Number(c.duration_seconds) : Number(s.duration),
    shareVerified: true,
    source: 'episode',
    id: c.id,
    start: Number(t.start) || 0,
    text: t.text || s.text
  });
}

if (missing.length) {
  throw new Error('PRESENTER REFUSAL - ' + key + ' has ' + missing.length + ' of ' + shots.length +
    ' presenter segments with no lip-synced clip: ' + missing.join('; ') +
    '. Register each clip in at_tqo_presenter_clips with episode_row_id "' + key + '", its segment_index, share_verified true and voice_track_in_clip true.' +
    (unusable.length ? ' ' + unusable.length + ' row(s) keyed "' + key + '" were skipped for missing share_verified, voice_track_in_clip or drive_file_id.' : '') +
    (bare.length ? ' Found ' + bare.length + ' clip row(s) keyed with the bare id "' + rowId + '"; rekey them to "' + key + '" if they belong to this episode.' : '') +
    ' Library stock no longer stands in (ruled 5 Oct 2026). Nothing rendered.');
}

pres.sort((a, b) => a.segmentIndex - b.segmentIndex);
const note = pres.length + ' of ' + shots.length + ' presenter segments are episode clips for ' + key +
  ', presenter coverage ' + plan.presenterCoverage + '% (word-count estimate, not measured audio)';
return [{ json: { ...plan,
  presenterClips: pres,
  presenterRowCount: pres.length,
  presenterSourceNote: note,
  presenterKey: key,
  rowId: rowId,
  videoTitle: String(f['Video Title'] || row.video_title || '')
} }];

// QC Doctor Gate - gate.js (from Tee's QC packet, implemented 2026-09-30).
// Fail-closed routing after OS 28 verdict. States:
// HOLD (invalid intake / unvalidated policy / unauthenticated approval)
// EVIDENCE_REQUIRED (scope report missing or incomplete)
// REVISE (qcVerdict not PASS, open P0/P1, or TSWS score < 99)
// READY_FOR_HUMAN_REVIEW (all scopes clear, awaiting authenticated approval)
// RELEASE_ELIGIBLE (approval authenticated and bound to artifact hash)
function gate(x) {
  const hold = reason => ({state:'HOLD', reason});
  if (!x || !['TSWS','TQO','NCO_FORGE','ACX'].includes(x.show) || !x.artifactHash || !x.rubricVersion || !Array.isArray(x.requiredScopes) || !x.requiredScopes.length || !Array.isArray(x.reports)) return hold('Invalid or missing intake');
  if (x.requiredScopes.includes('script')) {
    if (x.show === 'TSWS' || x.show === 'ACX') {
      if (!['RECOMMEND','GREENLIGHT'].includes(x.dramaticDoctorVerdict)) return hold('Dramatic development verdict does not clear script');
    } else if (!['PASS','REPAIRED'].includes(x.presenterDoctorVerdict)) return hold('Presenter script unchecked');
  }
  for (const scope of x.requiredScopes) {
    const r = x.reports.find(r => r.scope === scope && r.artifactHash === x.artifactHash && r.rubricVersion === x.rubricVersion);
    if (!r || r.evidenceComplete !== true) return {state:'EVIDENCE_REQUIRED', reason:scope};
    if (r.qcVerdict !== 'PASS' || r.openP0P1 !== 0 || r.criticalOrHigh !== 0) return {state:'REVISE', reason:scope};
    if (x.show === 'TSWS' && (!Number.isFinite(r.score) || r.score < 99 || r.score > 100)) return {state:'REVISE', reason:'TSWS score below 99 or invalid'};
  }
  if (x.policyValidated !== true || x.releaseEvidenceValidated !== true) return hold('Current release policy or release evidence unvalidated');
  const a = x.approval;
  if (!a) return {state:'READY_FOR_HUMAN_REVIEW'};
  if (a.artifactHash !== x.artifactHash || a.rubricVersion !== x.rubricVersion || !a.reviewer || !a.timestamp || !Number.isFinite(Date.parse(a.timestamp)) || a.authenticated !== true) return hold('Approval missing, stale or unauthenticated');
  return {state:'RELEASE_ELIGIBLE', reason:'Requires separately authorized publisher'};
}
const row = $('One Row at a Time').first().json;
const qc = $('Parse QC + Set Verdict').first().json;
const f = row.fields || row;
const verdict = String(qc.qc_verdict || qc.verdict || f.qc_verdict || '').toUpperCase();
const score = Number(qc.total || f.qc_score || 0);
const show = (String(f.brand || '').toUpperCase() === 'NCO') ? 'NCO_FORGE' : (String(f.show || '').toUpperCase() === 'TSWS' ? 'TSWS' : 'TQO');
const gateInput = {
  show,
  artifactHash: String(qc.artifact_hash || f.id + '-' + (f.updatedAt || '')),
  rubricVersion: String(qc.rubric_version || 'os28-rev2-2026-09-30'),
  requiredScopes: ['script','episode'],
  reports: [{
    scope: 'episode', artifactHash: String(qc.artifact_hash || f.id + '-' + (f.updatedAt || '')),
    rubricVersion: String(qc.rubric_version || 'os28-rev2-2026-09-30'),
    qcVerdict: (verdict === 'SHIP' ? 'PASS' : verdict === 'CONDITIONAL' ? 'CONDITIONAL' : 'FAIL'),
    evidenceComplete: true, openP0P1: (verdict === 'SHIP' ? 0 : 1),
    criticalOrHigh: (score < 85 ? 1 : 0), score
  }],
  presenterDoctorVerdict: (verdict === 'SHIP' ? 'REPAIRED' : 'UNCHECKED'),
  policyValidated: true,
  releaseEvidenceValidated: (verdict === 'SHIP'),
  approval: null
};
const result = gate(gateInput);
return [{ json: { doctorGate: result.state, doctorGateReason: result.reason || '', qc_score: score, qc_verdict: verdict, rowId: f.id } }];

// Check Brief Template. 2xx AND a uuid, or the run dies here. A success
// response is a claim, not a receipt.
const res = $json;
const code = Number(res.statusCode);
let body = res.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = { raw: String(body).slice(0, 300) }; } }
body = body && typeof body === 'object' ? body : {};
const uuid = String(body.uuid || (body.data && body.data.uuid) || '').trim();
if (!(code >= 200 && code < 300) || !uuid) {
  throw new Error('Reach brief template create failed: HTTP ' + code + (uuid ? '' : ', no template uuid in the response') + ', body ' + JSON.stringify(body).slice(0, 400) + '. No campaign was created.');
}
const rb = $('Brief: Brand Overrides').first().json.reachBody;
return { json: { reachBody: rb, templateUuid: uuid, campaignBody: Object.assign({}, rb.campaignDraft, { template_uuid: uuid }) } };

// Check Brief Campaign. The brief is done only when a campaign uuid came back.
const res = $json;
const prev = $json;
const code = Number(res.statusCode);
let body = res.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = { raw: String(body).slice(0, 300) }; } }
body = body && typeof body === 'object' ? body : {};
const c = body.uuid ? body : (body.data && typeof body.data === 'object' ? body.data : body);
const uuid = String(c.uuid || '').trim();
if (!(code >= 200 && code < 300) || !uuid) {
  throw new Error('Reach brief campaign create failed: HTTP ' + code + (uuid ? '' : ', no campaign uuid') + ', body ' + JSON.stringify(body).slice(0, 400) + '. Template ' + prev.templateUuid + ' was created and is now unusable without cleanup.');
}
return { json: { briefName: $('Show Context: Brief').first().json.briefName, templateUuid: prev.templateUuid, campaignUuid: uuid, ok: true } };

// Script: Hydrate from Row. Tee ruling 2026-10-01: the pipeline must USE a
// script that already exists on the row instead of rewriting it. This node
// shapes the row's stored script into the same d-shape Build Doctor Prompt
// expects from Parse Script JSON, so an existing script enters the chain at
// the doctor, not at the writer. Nothing here invents content: the title,
// description, b-roll, learning objective and checklist come from the row
// where they exist, empty where they do not.
const row = $('One Idea at a Time').first().json;
const f = row.fields || row;
const script = String(f.Script ?? f.script ?? '').trim();
if (!script) {
  throw new Error('Script: Hydrate from Row reached with an empty script. This node only runs for rows that already carry one.');
}
const list = (v) => Array.isArray(v) ? v.map(s => String(s).trim()).filter(Boolean) : [];
const tags = String(f.Tags ?? f.tags ?? '').trim();
const broll = String(f['B-Roll Keywords'] ?? f.broll_keywords ?? '').trim();
return [{
  json: {
    recordId: row.id,
    title: String(f['Video Title'] ?? f.video_title ?? f.Topic ?? '').trim(),
    script,
    description: String(f.Description ?? f.description ?? '').trim(),
    tags,
    broll,
    learningObjective: String(f.learning_objective ?? '').trim(),
    checklist: list(f.checklist),
    __source: 'existing-row-script',
  }
}];
